(window.WCD=window.WCD||[]).push(["classique",[["Q192185",1,"compositeur","Aaron Copland","PC","Aaron Copland, né le 14 novembre 1900 à Brooklyn et mort le 2 décembre 1990 à Tarrytown, est un compositeur, écrivain sur la musique, pianiste et chef d'orchestre américain.",117,"fr:Aaron_Copland","c:0/05/Aaron_Copland_1970.JPG"],["Q78475",2,"compositeur","Alban Berg","C","Alban Maria Johannes Berg est un compositeur autrichien, né le 9 février 1885 à Vienne et mort dans la même ville le 24 décembre 1935.",119,"fr:Alban_Berg","c:d/d6/WP_Alban_Berg.jpg"],["Q164004",3,"compositeur","Alexandre Borodine","C","Alexandre Porfirievitch Borodine, né le 31 octobre 1833 à Saint-Pétersbourg et mort le 15 février 1887 dans cette même ville, est un compositeur, chimiste et médecin russe. Il est l'auteur de l'opéra Le Prince Igor et de ses célèbres Danses polovtsiennes.",118,"fr:Alexandre_Borodine","c:7/70/Borodin.jpg"],["Q185647",4,"compositeur","Alexandre Scriabine","C","Alexandre Nikolaïevitch Scriabine est un pianiste, poète et compositeur russe né à Moscou le 25 décembre 1871 et mort à Moscou le 27 avril 1915. Il est l'un des représentants les plus importants de la musique moderne et de l'avant-garde musicale à l'aube de la Première guerre mondiale, et il est souvent considéré comme l'un des compositeurs les plus marquants du début du XXe siècle.",119,"fr:Alexandre_Scriabine","c:5/53/Skrjabin_Alexander.jpg"],["Q180975",5,"compositeur","Andrew Lloyd Webber","L","Andrew Lloyd Webber, baron Lloyd-Webber, est un compositeur britannique né le 22 mars 1948 à Kensington, qui s'est surtout rendu célèbre par ses comédies musicales, notamment Cats et The Phantom of the Opera. Ses œuvres font partie des comédies musicales ayant été le plus longtemps à l’affiche.",114,"fr:Andrew_Lloyd_Webber","c:1/1b/AndrewLloydWebber-byPhilipRomano.jpg"],["Q217619",6,"compositeur","Anthony Burgess","PC","Anthony Burgess, né John Anthony Burgess Wilson le 25 février 1917 à Hapurhey et mort le 25 novembre 1993 à St. John's Wood, est un écrivain, musicien et linguiste britannique.","Anthony Burgess, né John Anthony Burgess Wilson le 25 février 1917 à Hapurhey et mort le 25 novembre 1993 à St.","fr:Anthony_Burgess","c:1/16/Anthony_Burgess_appearing_on_%22After_Dark%22%2C_21_May_1988.jpg"],["Q81752",7,"compositeur","Anton Bruckner","C","Anton Bruckner, né le 4 septembre 1824 à Ansfelden et mort le 11 octobre 1896 à Vienne, est un compositeur et organiste autrichien. Figure éminente du romantisme allemand, il rencontre Richard Wagner en septembre 1873, ce qui influença la composition de sa 3e symphonie. Sa musique polyphonique et théologique, à l'orchestration par blocs différenciés à partir d'une cellule de base, fut desservie par la critique et un auditoire viennois acquis à la musique de Brahms.",119,"fr:Anton_Bruckner","c:a/aa/Joseph_Anton_Bruckner_%281868%29.jpg"],["Q190933",8,"compositeur","Anton Webern","C","Anton Webern, né le 3 décembre 1883 à Vienne et mort le 15 septembre 1945 à Mittersill, est un compositeur et chef d'orchestre autrichien. Un des premiers élèves d’Arnold Schönberg, il appartient au premier cercle de la Seconde école de Vienne.",114,"fr:Anton_Webern","c:1/13/Anton_Webern_%281883%E2%80%931945%29_1927_%C2%A9_Georg_Fayer_%281891%E2%80%931950%29_OeNB_10450290.png"],["Q51088",9,"compositeur","Antonio Salieri","R","Antonio Salieri, né le 18 août 1750 à Legnago et mort le 7 mai 1825 à Vienne, est un compositeur vénitien.",null,"fr:Antonio_Salieri","c:0/07/Antonio_Salieri_painted_by_Joseph_Willibrord_M%C3%A4hler.jpg"],["Q1340",10,"compositeur","Antonio Vivaldi","L","Antonio Lucio Vivaldi, né le 4 mars 1678 à Venise et mort le 28 juillet 1741 à Vienne, est un violoniste et compositeur de musique baroque italien. Il était également prêtre de l'Église catholique.",119,"fr:Antonio_Vivaldi","c:1/1b/Antonio_Vivaldi.jpg",{"cats":["classique","italie","personnalites"]}],["Q7298",11,"compositeur","Antonín Dvořák","R","Antonín Dvořák, né le 8 septembre 1841 à Nelahozeves et mort le 1er mai 1904 à Prague, est un compositeur tchèque originaire de Bohême. Il est l'un des premiers compositeurs tchèques à acquérir une renommée internationale et l'un des plus grands compositeurs de la seconde moitié du XIXe siècle. Très polyvalent, il s'illustre aussi bien dans les domaines de la musique de chambre que de la musique orchestrale, de la musique religieuse ou de l'opéra.",113,"fr:Antonín_Dvořák","c:d/d7/Jan_Langhans_Antonin_Dvorak_1904_%28cropped%29.jpg"],["Q152293",12,"compositeur","Aram Khatchatourian","C","Aram Ilitch Khatchatourian est un compositeur soviétique arménien, né le 24 mai 1903 à Tiflis et mort le 1er mai 1978 à Moscou.",119,"fr:Aram_Khatchatourian","c:8/8f/Aram_Khachaturian%2C_Pic%2C_17.jpg"],["Q154770",13,"compositeur","Arnold Schönberg","PC","Arnold Schönberg, ou Arnold Schoenberg est un compositeur, peintre et théoricien autrichien né le 13 septembre 1874 à Vienne, et mort le 13 juillet 1951 à Los Angeles. Deux siècles après Jean-Sébastien Bach et Jean-Philippe Rameau, qui avaient posé les fondements de la musique tonale, il chercha à émanciper la musique de la tonalité et inventa le dodécaphonisme, qui aura une influence marquante sur une part de la musique du XXe siècle.",117,"fr:Arnold_Schönberg","c:a/ad/Arnold_Schoenberg_la_1948.jpg"],["Q183182",14,"compositeur","Arthur Rubinstein","C","Arthur Rubinstein, né le 28 janvier 1887 à Łódź et mort le 20 décembre 1982 à Genève, est un pianiste polonais naturalisé américain. Artiste mondain, très médiatisé et populaire, un des musiciens ayant donné le plus de concerts au cours de cette période, il figure parmi les plus grands pianistes du XXe siècle.",110,"fr:Arthur_Rubinstein","c:7/78/Optreden_Arthur_Rubinstein_in_Concertgebouw%2C_Bestanddeelnr_913-5228.jpg"],["Q189534",15,"compositeur","Arvo Pärt","PC","Arvo Pärt, né le 11 septembre 1935 à Paide en Estonie, est un compositeur estonien. Souvent associé au mouvement de musique minimaliste, il est considéré comme un des principaux compositeurs contemporains.","Arvo Pärt, né le 11 septembre 1935 à Paide en Estonie, est un compositeur estonien.","fr:Arvo_Pärt","c:1/16/Composer_Arvo_P%C3%A4rt_%285326739069%29.jpg"],["Q172505",16,"compositeur","Astor Piazzolla","C","Ástor Piazzolla, né le 11 mars 1921 à Mar del Plata et mort le 4 juillet 1992 à Buenos Aires, est un compositeur et bandonéoniste argentin. Il est considéré comme le musicien le plus important de la seconde moitié du XXe siècle pour la musique de tango.",115,"fr:Astor_Piazzolla","c:5/53/Astor_Piazzolla.jpg"],["Q48173",17,"compositeur","Bedřich Smetana","C","Bedřich Smetana, né le 2 mars 1824 à Litomyšl et mort le 12 mai 1884 à Prague, est un compositeur tchèque. Il est célèbre pour son poème symphonique Vltava, le deuxième d'un cycle de six intitulé Má Vlast, ainsi que pour son opéra La Fiancée vendue.","Bedřich Smetana, né le 2 mars 1824 à Litomyšl et mort le 12 mai 1884 à Prague, est un compositeur tchèque.","fr:Bedřich_Smetana","c:7/74/FriedrichSmetana.jpg"],["Q150767",18,"compositeur","Benjamin Britten","PC","Edward Benjamin Britten, né le 22 novembre 1913 à Lowestoft dans le Suffolk, et mort le 4 décembre 1976 à Aldeburgh, est un compositeur, chef d'orchestre, altiste et pianiste britannique.",116,"fr:Benjamin_Britten","c:3/30/Benjamin_Britten%2C_London_Records_1968_publicity_photo_for_Wikipedia.jpg"],["Q83326",19,"compositeur","Béla Bartók","PC","Béla Bartók (prononciation: /ˈbeːlɒ ˈbɒrtoːk/, né le 25 mars 1881 à Nagyszentmiklós en Autriche-Hongrie et mort le 26 septembre 1945 à New York est un compositeur et pianiste hongrois.",117,"fr:Béla_Bartók","c:6/66/Bart%C3%B3k_B%C3%A9la_1927.jpg"],["Q150445",20,"compositeur","Camille Saint-Saëns","R","Camille Saint-Saëns (), né le 9 octobre 1835 à Paris et mort le 16 décembre 1921 à Alger, est un pianiste, organiste et compositeur français de l'époque romantique.",119,"fr:Camille_Saint-Saëns","c:0/0b/Saintsaens.jpg"],["Q154812",21,"compositeur","Carl Maria von Weber","C","Carl Maria Friedrich Ernst von Weber est un compositeur allemand de musique romantique né le 18 novembre 1786 à Eutin, près de Lübeck, et mort le 5 juin 1826 à Londres, dans le quartier de Marylebone.",118,"fr:Carl_Maria_von_Weber","c:4/42/Caroline_Bardua_-_Bildnis_des_Komponisten_Carl_Maria_von_Weber.jpg"],["Q44086",22,"compositeur","Carl Orff","PC","Carl Orff, né le 10 juillet 1895 à Munich et mort le 29 mars 1982 dans la même ville, est un compositeur allemand. Son œuvre la plus connue est Carmina Burana.","Carl Orff, né le 10 juillet 1895 à Munich et mort le 29 mars 1982 dans la même ville, est un compositeur allemand.","fr:Carl_Orff","c:8/86/Carl_Orff_profile_view.jpg"],["Q76428",23,"compositeur","Carl Philipp Emanuel Bach","C","Carl Philipp Emanuel Bach, né à Weimar, dans le duché de Saxe-Weimar, le 8 mars 1714 et mort à Hambourg le 14 décembre 1788, est un compositeur, musicien et musicologue allemand, membre de l'École de Berlin.",118,"fr:Carl_Philipp_Emanuel_Bach","c:1/19/CPEB_by_L%C3%B6hr.jpg"],["Q180278",24,"compositeur","Charles Gounod","C","Charles-François Gounod, né le 17 juin 1818 à Paris et mort le 18 octobre 1893 à Saint-Cloud, est un compositeur français. Il a composé douze opéras, dont le plus populaire reste Faust. Son Roméo et Juliette figure également au répertoire international. Il a composé une abondante musique sacrée, de nombreuses chansons et des pièces courtes populaires, notamment son Ave Maria et la Marche funèbre d’une marionnette.",112,"fr:Charles_Gounod","c:e/e4/Charles_Gounod_%281890%29_by_Nadar.jpg"],["Q130759",25,"compositeur","Christoph Willibald Gluck","C","Christoph Willibald, Ritter von Gluck est un compositeur de la période classique, né à Erasbach, en Bavière, le 2 juillet 1714 et mort à Vienne, en Autriche, le 15 novembre 1787.",113,"fr:Christoph_Willibald_Gluck","c:9/91/Joseph_Siffred_Duplessis_-_Christoph_Willibald_Gluck_-_Google_Art_Project.jpg"],["Q132232",26,"compositeur","Clara Schumann","PC","Clara Schumann, née Clara Wieck le 13 septembre 1819 à Leipzig et morte le 20 mai 1896 à Francfort-sur-le-Main, est une pianiste et compositrice allemande. Considérée comme l'une des plus grandes pianistes de l’époque romantique, elle compose des concertos pour piano et de la musique de chambre.",119,"fr:Clara_Schumann","c:e/e7/Franz_Hanfstaengl_-_Clara_Schumann_%281857%29.jpg"],["Q4700",27,"compositeur","Claude Debussy","E","Claude Debussy est un compositeur français né le 22 août 1862 à Saint-Germain-en-Laye et mort le 25 mars 1918 à Paris.",null,"fr:Claude_Debussy","c:c/c3/Claude_Debussy_by_Atelier_Nadar.jpg"],["Q151608",28,"compositeur","Claudio Abbado","C","Claudio Abbado, né le 26 juin 1933 à Milan et mort le 20 janvier 2014 à Bologne, est un chef d'orchestre italien.",null,"fr:Claudio_Abbado","c:3/31/Claudio_Abbado_Senato.jpg"],["Q50187",29,"compositeur","César Franck","C","César Franck, né le 10 décembre 1822 à Liège et mort le 8 novembre 1890 à Paris, est un organiste et compositeur belge, naturalisé français en 1870.",119,"fr:César_Franck","c:1/1c/C%C3%A9sar_Franck_by_Pierre_Petit.jpg"],["Q186264",30,"compositeur","Darius Milhaud","C","Darius Milhaud, né le 4 septembre 1892 à Marseille et mort à Genève le 22 juin 1974, est un compositeur français de musique classique.",115,"fr:Darius_Milhaud","c:9/98/Darius_Milhaud_b_Meurisse_1923.jpg"],["Q153637",31,"compositeur","Dietrich Buxtehude","C","Dieterich Buxtehude, né vers 1637 à Helsingborg ou Buxtehude ou Oldesloe et mort le 9 mai 1707 à Lübeck, est un musicien, organiste et compositeur allemand d'ascendance danoise. Établi à Lübeck, l'une des villes les plus actives sur le plan musical en son temps, il compose pour la liturgie, mais aussi pour des concerts spirituels ou profanes plaisant au public local, notamment les Abendmusiken, veillées musicales de l'Avent dont il fait une institution qui se perpétue jusqu'au XIXe siècle.",111,"fr:Dietrich_Buxtehude","c:4/46/Dieterich_Buxtehude.png"],["Q80135",32,"compositeur","Dmitri Chostakovitch","E","Dmitri Dmitrievitch Chostakovitch, né le 12 septembre 1906 à Saint-Pétersbourg dans l'Empire russe et mort le 9 août 1975 à Moscou en URSS, est un compositeur russe de la période soviétique.",116,"fr:Dmitri_Chostakovitch","c:a/ab/Dmitri_Shostakovich_credit_Deutsche_Fotothek_adjusted.jpg"],["Q167837",33,"compositeur","Domenico Scarlatti","C","Domenico Scarlatti, ou Giuseppe Domenico Scarlatti, né le 26 octobre 1685 à Naples et mort le 23 juillet 1757 à Madrid, est un compositeur baroque et claveciniste virtuose italien.",119,"fr:Domenico_Scarlatti","c:9/9f/Retrato_de_Domenico_Scarlatti.jpg"],["Q80621",34,"compositeur","Edvard Grieg","PC","Edvard Grieg, né le 15 juin 1843 à Bergen et mort le 4 septembre 1907 dans la même ville, est un compositeur et pianiste norvégien de la période romantique tardive. Il est le compositeur norvégien qui a connu le plus grand succès international et, à l'instar d'Henrik Ibsen, Bjørnstjerne Bjørnson et d'autres artistes de la fin du XIXe siècle, il joue un rôle majeur dans la construction culturelle de la nation norvégienne durant la période précédant la dissolution de l'union avec la Suède en 1905.",111,"fr:Edvard_Grieg","c:c/c0/Edvard_Grieg_%281888%29_by_Elliot_and_Fry_-_02.jpg"],["Q179631",35,"compositeur","Edward Elgar","PC","Edward Elgar, né le 2 juin 1857 à Lower Broadheath, près de Worcester, et mort le 23 février 1934 à Worcester, 1er baronnet Elgar de Broadheath, est un compositeur et chef d'orchestre britannique dont les œuvres les plus connues sont entrées dans le répertoire classique international: les Variations Enigma, les marches Pomp and Circumstance, son concerto pour violon, son concerto pour violoncelle et deux symphonies.",114,"fr:Edward_Elgar","c:0/0a/Edward_Elgar_1857_-_1934.jpg"],["Q23848",36,"compositeur","Ennio Morricone","E","Ennio Morricone, né le 10 novembre 1928 à Rome et mort le 6 juillet 2020 dans la même ville, est un compositeur, musicien, producteur, arrangeur et chef d'orchestre italien. Il a signé une partie de ses compositions sous les pseudonymes Dan Savio et Leo Nichols.",112,"fr:Ennio_Morricone","c:5/5f/Ennio_Morricone_Cannes_2007.jpg",{"cats":["classique","italie"]}],["Q187192",37,"compositeur","Erik Satie","R","Erik Satie, né le 17 mai 1866 à Honfleur et mort le 1er juillet 1925 à Paris 14e, est un compositeur et pianiste français.",112,"fr:Erik_Satie","c:7/77/Satie-erik-4ff9d0bde1749.jpg"],["Q57286",38,"compositeur","Fanny Mendelssohn","C","Fanny Mendelssohn, appelée aussi Fanny Hensel, née le 14 novembre 1805 à Hambourg et morte le 14 mai 1847 à Berlin, est une compositrice et pianiste allemande. Membre de la famille Mendelssohn, elle est la sœur du compositeur Felix Mendelssohn.",119,"fr:Fanny_Mendelssohn","c:0/0b/Fannymendelssohn-improved.jpg"],["Q46096",39,"compositeur","Felix Mendelssohn","R","Jakob Ludwig Felix Mendelssohn Bartholdy, plus couramment appelé Felix Mendelssohn, né le 3 février 1809 à Hambourg et mort le 4 novembre 1847 à Leipzig, est un compositeur, chef d'orchestre et pianiste allemand du début de la période romantique. Membre de la famille Mendelssohn, il est le petit-fils du philosophe et rabbin Moses Mendelssohn, le fils du banquier et philanthrope Abraham Mendelssohn Bartholdy et le frère de la compositrice Fanny Mendelssohn.",118,"fr:Felix_Mendelssohn","c:c/c2/Felix_Mendelssohn_Bartholdy_by_Eduard_Magnus_%281833%29.jpg"],["Q191408",40,"compositeur","Francis Poulenc","C","Francis Poulenc est un compositeur et pianiste français, né le 7 janvier 1899 à Paris où il est mort le 30 janvier 1963.",null,"fr:Francis_Poulenc","c:a/a2/Francis_Poulenc_and_Wanda_Landowska_%28cropped%29.jpg"],["Q41309",41,"compositeur","Franz Liszt","E","Franz Liszt est un compositeur, transcripteur et pianiste virtuose hongrois, né le 22 octobre 1811 à Doborján en Hongrie et mort le 31 juillet 1886 à Bayreuth en Bavière.",112,"fr:Franz_Liszt","c:6/69/Liszt-kaulbach.jpg"],["Q7312",42,"compositeur","Franz Schubert","E","Franz Schubert, né le 31 janvier 1797 à Lichtental et mort le 19 novembre 1828 à Vienne, est un compositeur autrichien.",null,"fr:Franz_Schubert","c:0/0d/Franz_Schubert_by_Wilhelm_August_Rieder_1875.jpg",{"cats":["classique","personnalites"]}],["Q50186",43,"compositeur","François Couperin","C","François Couperin, né le 10 novembre 1668 à Paris et mort le 11 septembre 1733 dans la même ville, est un important compositeur, organiste et claveciniste français de la période baroque. Il est surnommé « Couperin le Grand » pour le distinguer d'autres membres de cette famille qui compte de nombreux musiciens.",115,"fr:François_Couperin","c:c/c4/Francois_Couperin_2.jpg"],["Q1268",44,"compositeur","Frédéric Chopin","L","Frédéric Chopin, né Fryderyk Franciszek Chopin le 1er mars 1810 à Żelazowa Wola et mort le 17 octobre 1849 à Paris, est un compositeur et pianiste d'ascendance franco-polonaise, connu pour son œuvre presque exclusivement pianistique, et qui inclut toujours le piano.",119,"fr:Frédéric_Chopin","c:e/e8/Frederic_Chopin_photo.jpeg",{"cats":["classique","personnalites"]}],["Q104919",45,"compositeur","Gabriel Fauré","C","Gabriel Fauré, né le 12 mai 1845 à Pamiers dans l'Ariège et mort le 4 novembre 1924 à Paris, est un compositeur, organiste, pianiste et pédagogue musical français.",112,"fr:Gabriel_Fauré","c:0/09/Gabriel_Faur%C3%A9_Paul_Nadar_1905.JPG"],["Q101698",46,"compositeur","Gaetano Donizetti","C","Gaetano Donizetti, né le 29 novembre 1797 à Bergame et mort le 8 avril 1848 dans la même ville, est un compositeur italien. Avec Gioachino Rossini et Vincenzo Bellini, il fait partie des trois grands compositeurs d'opéra de l'ère du bel canto italien et marque la naissance de la musique romantique italienne.",114,"fr:Gaetano_Donizetti","c:1/12/Francesco_Coghetti%2C_Ritratto_di_Gaetano_Donizetti.JPG"],["Q7302",47,"compositeur","Georg Friedrich Haendel","R","Georg Friedrich Haendel ou Georg Friederich Händel (en anglais George Frideric Handel) est un compositeur saxon, devenu anglais par naturalisation, né le 23 février 1685 à Halle-sur-Saale et mort le 14 avril 1759 à Westminster.",119,"fr:Georg_Friedrich_Haendel","c:f/fa/George_Frideric_Handel_by_Balthasar_Denner.jpg"],["Q75854",48,"compositeur","Georg Philipp Telemann","C","Georg Philipp Telemann est un compositeur allemand.",null,"fr:Georg_Philipp_Telemann","c:d/d5/Telemann.jpg"],["Q123829",49,"compositeur","George Gershwin","R","George Gershwin, pseudonyme de Jacob Gershowitz, est un compositeur et chef d'orchestre américain, né le 26 septembre 1898 à Brooklyn et mort le 11 juillet 1937 à Los Angeles.",117,"fr:George_Gershwin","c:6/68/George_Gershwin_1937.jpg"],["Q56158",50,"compositeur","Georges Bizet","PC","Georges Bizet, né Alexandre-César-Léopold Bizet le 25 octobre 1838 à Paris et mort le 3 juin 1875 à Bougival, est un compositeur français. Un des compositeurs les plus connus de la période romantique, il l'est surtout pour ses opéras, dont le très populaire Carmen, et ses suites orchestrales, créés sur une courte période, puisqu'il meurt à l'âge de 36 ans.",116,"fr:Georges_Bizet","c:9/96/Georges_bizet.jpg"],["Q7311",51,"compositeur","Giacomo Puccini","R","Giacomo Puccini, de son nom complet Giacomo Antonio Domenico Michele Secondo Maria Puccini, né le 22 décembre 1858 à Lucques et mort le 29 novembre 1924 à Bruxelles, est un compositeur italien, considéré comme l'un des plus grands compositeurs de la fin du XIXe siècle et du début du XXe siècle.",116,"fr:Giacomo_Puccini","c:9/9b/GiacomoPuccini.jpg",{"cats":["classique","italie"]}],["Q9726",52,"compositeur","Gioachino Rossini","PC","Gioachino Rossini — Gioacchino Rossini pour certains auteurs et Giovacchino Antonio Rossini pour l'état civil —, né le 29 février 1792 à Pesaro et mort le 13 novembre 1868 à Passy, Paris, est un compositeur italien.",118,"fr:Gioachino_Rossini","c:f/f5/Composer_Rossini_G_1865_by_Carjat_-_Restoration.jpg",{"cats":["classique","italie"]}],["Q7317",53,"compositeur","Giuseppe Verdi","R","Giuseppe Fortunino Francesco Verdi, né Joseph Fortunin François Verdi le 10 octobre 1813 à Roncole et mort le 27 janvier 1901 à Milan, est un compositeur romantique italien. Son œuvre, composée essentiellement d'opéras, unissant le pouvoir mélodique à la profondeur psychologique et légendaire, est l'une des plus importantes de l'histoire du théâtre musical.",112,"fr:Giuseppe_Verdi","c:7/7c/Verdi-photo-Brogi.jpg",{"cats":["classique","italie","personnalites"]}],["Q200867",54,"compositeur","Gustav Holst","PC","Gustav Holst est un compositeur anglais. Bien que principalement connu pour sa suite orchestrale Les Planètes, il a composé un grand nombre d’œuvres de genres divers. Son style de composition particulier est le produit de plusieurs influences dont celle du renouveau des chansons populaires anglaises au début du XXe siècle.","Gustav Holst est un compositeur anglais.","fr:Gustav_Holst","c:0/01/Gustav_Holst.jpg"],["Q7304",55,"compositeur","Gustav Mahler","E","Gustav Mahler, né le 7 juillet 1860 à Kaliště dans l'empire d'Autriche et décédé le 18 mai 1911 à Vienne, est un pianiste, compositeur et chef d'orchestre autrichien.",112,"fr:Gustav_Mahler","c:6/61/Mahler_Gustav_von_Sz%C3%A9kely.png"],["Q76364",56,"compositeur","Hans Zimmer","M","Hans Zimmer, né le 12 septembre 1957 à Francfort-sur-le-Main, est un compositeur de musique de film et producteur de trames sonores allemand naturalisé américain.",116,"fr:Hans_Zimmer","c:2/2b/Hans-Zimmer-profile.jpg"],["Q1151",57,"compositeur","Hector Berlioz","PC","Hector Berlioz est un compositeur, chef d'orchestre, critique musical et écrivain français, né le 11 décembre 1803 à La Côte-Saint-André et mort le 8 mars 1869 à Paris.",119,"fr:Hector_Berlioz","c:c/cc/Berlioz_d%E2%80%99apr%C3%A8s_Pierre_Petit.png"],["Q9695",58,"compositeur","Henry Purcell","C","Henry Purcell, né le 10 septembre 1659 et mort le 21 novembre 1695 à Londres, est un musicien et compositeur anglais.",null,"fr:Henry_Purcell","c:d/df/Henry_Purcell_Closterman.jpg"],["Q191957",59,"compositeur","Ignacy Paderewski","C","Ignacy Jan Paderewski, né le 6 novembre 1860 à Kuryłówka en Podolie et mort le 29 juin 1941 à New York, est un pianiste, compositeur, mécène, philanthrope, homme d'État et diplomate polonais. Ce grand virtuose attirait à ses concerts des foules enthousiastes, fascinées par son charisme hors du commun. Il n’hésitait pas à se servir de sa popularité pour défendre la cause de l’indépendance de la Pologne. Il épouse en deuxièmes noces la militante féministe et humanitaire Helena Maria Paderewska von Rosen.",110,"fr:Ignacy_Paderewski","c:8/8e/Ignacy_Paderewski_1894.jpg"],["Q41555",60,"compositeur","Jacques Offenbach","PC","Jacques Offenbach /ʒak ɔfɛnbak/, né le 20 juin 1819 à Cologne et mort le 5 octobre 1880 à Paris, est un compositeur et violoncelliste prussien naturalisé français.",118,"fr:Jacques_Offenbach","c:c/c1/Jacques_Offenbach_by_Nadar.jpg"],["Q106221",61,"compositeur","James Horner","R","James Horner, né le 14 août 1953 à Los Angeles et mort le 22 juin 2015 près de Santa Barbara, est un compositeur de musique de films américain.",115,"fr:James_Horner","c:9/9f/James-horner-07.jpg"],["Q45682",62,"compositeur","Jean Sibelius","R","Jean Sibelius, né le 8 décembre 1865 à Hämeenlinna, dans le grand-duché de Finlande, et mort le 20 septembre 1957 à Järvenpää, tout près d'Helsinki, est un compositeur finlandais de musique classique. Il est, avec Johan Ludvig Runeberg, l'un des Finlandais qui symbolisent le mieux la naissance de l'identité nationale finlandaise.",115,"fr:Jean_Sibelius","c:2/2b/Jean_Sibelius%2C_1913.jpg"],["Q1192",63,"compositeur","Jean-Baptiste Lully","C","Jean-Baptiste Lully né le 28 novembre 1632 à Florence et mort le 22 mars 1687 à Paris, est un compositeur et violoniste français d’origine italienne de la période baroque actif en France sous le règne de Louis XIV. Naturalisé français en 1661, il est nommé, la même année, surintendant de la musique du roi et l'année suivante maître de musique de la famille royale.",119,"fr:Jean-Baptiste_Lully","c:8/85/Paul_Mignard_-_Jean-Baptiste_Lully.jpg"],["Q1145",64,"compositeur","Jean-Philippe Rameau","C","Jean-Philippe Rameau est un compositeur français et théoricien de la musique, né le 25 septembre 1683 à Dijon et mort le 12 septembre 1764 à Paris.",117,"fr:Jean-Philippe_Rameau","c:9/98/Attribu%C3%A9_%C3%A0_Joseph_Aved%2C_Portrait_de_Jean-Philippe_Rameau_%28vers_1728%29_-_001.jpg"],["Q1339",65,"compositeur","Jean-Sébastien Bach","L","Jean-Sébastien Bach est un compositeur et musicien allemand né le 21 mars 1685 à Eisenach dans le duché de Saxe-Eisenach et mort le 28 juillet 1750 à Leipzig. Il est souvent surnommé le « Cantor de Leipzig ».",106,"fr:Jean-Sébastien_Bach","c:6/6a/Johann_Sebastian_Bach.jpg",{"cats":["classique","personnalites"]}],["Q106641",66,"compositeur","Johann Christian Bach","C","Johann Christian Bach, francisé Jean-Chrétien Bach, né le 5 septembre 1735 à Leipzig et mort le 1er janvier 1782 à Londres, est un compositeur et organiste allemand, dix-huitième des vingt enfants de Jean-Sébastien Bach, le onzième des treize enfants d’Anna-Magdalena et le plus jeune des onze fils de J.-S. Bach. Il fut surnommé le « Bach de Milan » et le « Bach de Londres ».",114,"fr:Johann_Christian_Bach","c:4/45/Johann_Christian_Bach_by_Thomas_Gainsborough.jpg"],["Q76485",67,"compositeur","Johann Pachelbel","C","Johann Pachelbel est un compositeur et organiste allemand de la période baroque, baptisé le 1er septembre 1653 à Nuremberg et mort dans la même ville le 3 mars 1706.",112,"fr:Johann_Pachelbel",""],["Q83309",68,"compositeur","Johann Strauss II","PC","Johann Strauss II, dit Johann Strauss fils ou Johann Strauss le jeune, né le 25 octobre 1825 à Vienne et mort le 3 juin 1899 dans la même ville, est un compositeur autrichien.",119,"fr:Johann_Strauss_II","c:3/3a/Johann_Strauss_II_%283%29.jpg"],["Q7294",69,"compositeur","Johannes Brahms","E","Johannes Brahms, né le 7 mai 1833 à Hambourg et mort le 3 avril 1897 à Vienne, est un compositeur, pianiste et chef d'orchestre allemand. Johannes Brahms est l'un des plus importants musiciens de la période romantique. Certains le considèrent comme le « successeur » de Beethoven dont Hans von Bülow qui décrit sa première symphonie comme étant « la Dixième symphonie de Beethoven ».",115,"fr:Johannes_Brahms","c:1/15/JohannesBrahms.jpg"],["Q111074",70,"compositeur","John Barry","PC","Jonathan Barry Prendergast, dit John Barry, né le 3 novembre 1933 à York et mort le 30 janvier 2011 à Oyster Bay, est un compositeur britannico-américain de musique de film.",117,"fr:John_Barry_(compositeur)","c:f/f8/John-barry-2006.jpg"],["Q180727",71,"compositeur","John Cage","PC","John Cage est un compositeur, poète et plasticien américain, né le 5 septembre 1912 à Los Angeles et mort le 12 août 1992 à New York.",116,"fr:John_Cage","c:2/23/John_Cage_%281988%29.jpg"],["Q131285",72,"compositeur","John Williams","L","John Towner Williams est un compositeur, chef d'orchestre et pianiste américain né le 8 février 1932 à New York.",null,"fr:John_Williams_(compositeur)","c:a/a4/John_Williams_2024.jpg"],["Q7349",73,"compositeur","Joseph Haydn","R","Franz Joseph Haydn — il n'utilisait jamais son premier prénom —, né le 31 mars 1732 à Rohrau sur la Leitha en Basse-Autriche et mort le 31 mai 1809 à Vienne, est un compositeur autrichien. Il incarne le classicisme viennois au même titre que Mozart et Beethoven, les trois compositeurs étant regroupés par la postérité sous le vocable de « trinité classique viennoise ».",109,"fr:Joseph_Haydn","c:0/05/Joseph_Haydn.jpg"],["Q194436",74,"compositeur","Jules Massenet","C","Jules Massenet est un compositeur français né le 12 mai 1842 à Montaud et mort le 13 août 1912 à Paris. Ses compositions étaient très populaires à la fin du XIXe siècle et au début du XXe siècle. Les opéras de Massenet sont connus pour leur beauté mélodique et pour leur représentation des émotions de l'amour et de la passion. Ses œuvres les plus connues incluent les opéras Manon, Werther et Thaïs. Sa musique est toujours populaire et régulièrement jouée dans le monde entier.","Jules Massenet est un compositeur français né le 12 mai 1842 à Montaud et mort le 13 août 1912 à Paris.","fr:Jules_Massenet","c:d/de/Jules_Massenet_by_Eug%C3%A8ne_Pirou%2C_edit_%28cropped%29.jpg"],["Q154556",75,"compositeur","Karlheinz Stockhausen","C","Karlheinz Stockhausen est un compositeur allemand né le 22 août 1928 à Mödrath et mort le 5 décembre 2007 à Kürten, en Allemagne. Son travail se construit autour de la musique électroacoustique, de la spatialisation du son et, les dernières années, de longs cycles de création qui aboutissent à des œuvres monumentales.",118,"fr:Karlheinz_Stockhausen","c:2/24/Stockhausen_March_2004_excerpt.jpg"],["Q152505",76,"compositeur","Leonard Bernstein","E","Leonard Bernstein, né sous le nom de Louis Bernstein, le 25 août 1918 à Lawrence, Massachusetts et mort le 14 octobre 1990 à New York, est un compositeur, chef d'orchestre et pianiste américain.",117,"fr:Leonard_Bernstein","c:1/11/Leonard_Bernstein_by_Jack_Mitchell_%28high_quality%29.jpg"],["Q156280",77,"compositeur","Leopold Mozart","C","Johann Georg Leopold Mozart, né le 14 novembre 1719 à Augsbourg et mort le 28 mai 1787 à Salzbourg, est un compositeur, professeur de musique et violoniste allemand. Aujourd'hui surtout connu comme père et professeur de Wolfgang Amadeus Mozart, il était assez célèbre à son époque pour sa méthode de violon, Versuch einer gründlichen Violinschule, diffusée dans toute l'Europe.",119,"fr:Leopold_Mozart","c:4/45/Leopold_Mozart.jpg"],["Q184933",78,"compositeur","Leoš Janáček","C","Leoš Janáček, né le 3 juillet 1854 à Hukvaldy et mort le 12 août 1928 à Ostrava, est un compositeur tchèque.",null,"fr:Leoš_Janáček","c:9/94/Leo%C5%A1_Jan%C3%A1%C4%8Dek_el_1914.png"],["Q230412",79,"compositeur","Lili Boulanger","C","Lili Boulanger, née Marie Juliette Boulanger le 21 août 1893 dans le 9e arrondissement de Paris et morte le 15 mars 1918 à Mézy-sur-Seine, est une compositrice française. Première femme à obtenir le prix de Rome de composition musicale, en 1913, elle est la sœur cadette de la pédagogue et compositrice Nadia Boulanger.",115,"fr:Lili_Boulanger","c:d/da/Lili_Boulanger_1.jpg"],["Q83182",80,"compositeur","Ludovico Einaudi","R","Ludovico Einaudi, né le 23 novembre 1955 à Turin, est un compositeur et pianiste italien.",null,"fr:Ludovico_Einaudi","c:e/e5/Ludovico_Einaudi_in_Tehran_12_%28cropped%292.jpg"],["Q255",81,"compositeur","Ludwig van Beethoven","M","Ludwig van Beethoven est un compositeur, pianiste et chef d'orchestre allemand né le 15 ou le 16 décembre 1770 à Bonn et mort le 26 mars 1827 à Vienne.",117,"fr:Ludwig_van_Beethoven","c:6/6f/Beethoven.jpg",{"cats":["classique","personnalites"]}],["Q207951",82,"compositeur","Léo Delibes","C","Clément Philibert Léo Delibes, dit Léo Delibes, né le 21 février 1836 à Saint-Germain-du-Val et mort le 16 janvier 1891 à Paris, est un compositeur français.",119,"fr:Léo_Delibes","c:2/24/Delibes_Leo_Luckhard.png"],["Q55524",83,"compositeur","Marc-Antoine Charpentier","C","Marc-Antoine Charpentier, né en Île-de-France en 1643 et mort à Paris le 24 février 1704, est un compositeur et chanteur baroque français.",111,"fr:Marc-Antoine_Charpentier","c:d/db/MA_Charpentier_II.jpg"],["Q105487",84,"compositeur","Maurice Jarre","C","Maurice Jarre est un compositeur français de musiques de scènes et de musiques de films, né le 13 septembre 1924 dans le 5e arrondissement de Lyon et mort le 28 mars 2009 à Malibu aux États-Unis.",117,"fr:Maurice_Jarre","c:4/4c/Identite-MauriceJarre-1950-Sacem.png"],["Q1178",85,"compositeur","Maurice Ravel","R","Maurice Ravel est un compositeur français né à Ciboure le 7 mars 1875 et mort à Paris 16e le 28 décembre 1937.",null,"fr:Maurice_Ravel","c:7/78/Maurice_Ravel_1925.jpg"],["Q132682",86,"compositeur","Modeste Moussorgski","C","Modeste Petrovitch Moussorgski, né le 9 mars 1839 à Karevo, près de Toropets dans le gouvernement de Pskov, et mort le 16 mars 1881 à Saint-Pétersbourg, est un compositeur russe. Il est d'abord célèbre par l'opéra Boris Godounov, par le poème symphonique Une nuit sur le mont Chauve et par la suite pour piano Tableaux d'une exposition — orchestrée par Maurice Ravel en 1922.",118,"fr:Modeste_Moussorgski","c:d/db/Modest_Musorgskiy%2C_1870.jpg"],["Q152043",87,"compositeur","Mstislav Rostropovitch","R","Mstislav Leopoldovitch Rostropovitch, né le 27 mars 1927 à Bakou et mort le 27 avril 2007 à Moscou, est un violoncelliste et chef d'orchestre russe.",106,"fr:Mstislav_Rostropovitch","c:7/7b/Mstislav_Rostropovich_1978.jpg"],["Q151976",88,"compositeur","Míkis Theodorákis","C","Míkis Theodorákis est un compositeur et homme politique grec né le 29 juillet 1925 sur l’île de Chios en Grèce et mort le 2 septembre 2021 à Athènes.",118,"fr:Míkis_Theodorákis","c:f/ff/Mikis_Theodorakis_Fabrik_070004.jpg"],["Q66075",89,"compositeur","Niccolò Paganini","PC","Niccolò Paganini, né le 27 octobre 1782 à Gênes et mort le 27 mai 1840 à Nice, est un violoniste, altiste, guitariste et compositeur génois.",117,"fr:Niccolò_Paganini","c:f/f7/NiccoloPaganini.jpeg"],["Q93227",90,"compositeur","Nikolaï Rimski-Korsakov","C","Nikolaï Andreïevitch Rimski-Korsakov, né le 6 mars 1844 à Tikhvine et mort le 8 juin 1908 à Lioubensk, est un compositeur russe. Il fut avec Tchaïkovski l'un des plus grands compositeurs russes de la seconde moitié du XIXe siècle. Il fit partie du « Groupe des Cinq » et fut professeur de musique, d'harmonie et d'orchestration au conservatoire de Saint-Pétersbourg.",109,"fr:Nikolaï_Rimski-Korsakov","c:7/7a/Nikolai_A._Rimsky-Korsakov.jpg"],["Q151593",91,"compositeur","Olivier Messiaen","C","Olivier Messiaen, né le 10 décembre 1908 à Avignon et mort le 27 avril 1992 à Clichy, est un compositeur, organiste et pianiste français.",118,"fr:Olivier_Messiaen","c:0/0a/Messiaen_Harcourt_1937_2.jpg"],["Q208537",92,"compositeur","Pablo Casals","C","Pau Carles Salvador Casals i Defilló, plus communément connu sous les noms de Pau Casals ou Pablo Casals, né le 29 décembre 1876 à El Vendrell et mort le 22 octobre 1973 à San Juan, est un violoncelliste, chef d'orchestre et compositeur espagnol.",114,"fr:Pablo_Casals","c:8/8c/Pablocasals.jpg"],["Q215556",93,"compositeur","Paul Dukas","C","Paul Dukas, né le 1er octobre 1865 dans le 1er arrondissement de Paris et mort le 17 mai 1935 dans le 16e arrondissement de la même ville, est un compositeur français. Perfectionniste et exigeant, il abandonne nombre de ses projets musicaux et ne publie qu'une poignée de ses œuvres.",105,"fr:Paul_Dukas","c:2/2a/Paul_Dukas_01.jpg"],["Q189729",94,"compositeur","Philip Glass","R","Philip Glass, né le 31 janvier 1937 à Baltimore dans le Maryland, est un musicien et compositeur de musique contemporaine américain. Il est considéré comme l'un des compositeurs les plus influents de la fin du XXe siècle. Il est, avec ses contemporains, La Monte Young, Terry Riley et Steve Reich, l'un des pionniers et l'un des représentants les plus éminents de la musique minimaliste, notamment de l'école répétitive, et de la musique classique des États-Unis.",107,"fr:Philip_Glass","c:9/91/Philip_Glass.jpg"],["Q156193",95,"compositeur","Pierre Boulez","C","Pierre Boulez, né le 26 mars 1925 à Montbrison et mort le 5 janvier 2016 à Baden-Baden, est un compositeur et chef d'orchestre français.",114,"fr:Pierre_Boulez","c:d/df/Pierre_Boulez_%281968%29.jpg"],["Q7315",96,"compositeur","Piotr Ilitch Tchaïkovski","L","Piotr Ilitch Tchaïkovski ou Tchaïkovsky est un compositeur russe de l’époque romantique né le 25 avril 1840 à Votkinsk et mort le 25 octobre 1893 à Saint-Pétersbourg.",118,"fr:Piotr_Ilitch_Tchaïkovski","c:0/02/Tchaikowsky.jpg",{"cats":["classique","personnalites"]}],["Q13894",97,"compositeur","Richard Strauss","R","Richard Georg Strauss, né le 11 juin 1864 à Munich et mort le 8 septembre 1949 à Garmisch-Partenkirchen, est un compositeur et chef d'orchestre allemand.",111,"fr:Richard_Strauss","c:2/2d/Strauss3.jpg"],["Q1511",98,"compositeur","Richard Wagner","L","Wilhelm Richard Wagner, né le 22 mai 1813 à Leipzig et mort le 13 février 1883 à Venise, est un compositeur, directeur de théâtre, écrivain et chef d'orchestre allemand de la période romantique. Il est particulièrement connu pour ses quatorze opéras et drames lyriques, dont les dix principaux sont régulièrement joués lors du Festival annuel, qu'il a créé en 1876, qui se déroule chaque été dans le palais des festivals de Bayreuth, conçu par lui-même pour l'exécution de ses œuvres.",118,"fr:Richard_Wagner","c:9/9d/RichardWagner.jpg",{"cats":["classique","personnalites"]}],["Q7351",99,"compositeur","Robert Schumann","R","Robert Schumann, né le 8 juin 1810 à Zwickau et mort le 29 juillet 1856 à Endenich, est un compositeur et pianiste allemand.",114,"fr:Robert_Schumann","c:f/fa/Robert_Schumann_1839.jpg"],["Q191499",100,"compositeur","Scott Joplin","PC","Scott Joplin, né le 24 novembre 1868 au Texas et mort le 1er avril 1917 à New York, est un pianiste et compositeur afro-américain. Bien que créateur dans plusieurs styles, y compris le classique et l'opéra, sa notoriété tient principalement à ses compositions de ragtime. Son talent dans ce style et plus largement dans la musique américaine en fait le plus notoire des compositeurs ayant écrit des ragtimes, notamment pour le Maple Leaf Rag, publié en 1899, et The Entertainer, publié en 1902.",114,"fr:Scott_Joplin","c:c/ca/Scott_Joplin_19072.jpg"],["Q49481",101,"compositeur","Sergueï Prokofiev","R","Sergueï Sergueïevitch Prokofiev, généralement appelé Serge Prokofiev en France, est un compositeur, pianiste et chef d'orchestre russe, né le 11 avril 1891 à Sontsovka et mort le 5 mars 1953 à Moscou. Il est l'auteur de nombreuses œuvres musicales allant de la symphonie au concerto, de la musique de film à des opéras ou des ballets et a été reconnu de son vivant comme un artiste d'avant-garde très créatif.",116,"fr:Sergueï_Prokofiev","c:0/03/Sergei_Prokofiev_circa_1918_over_Chair_Bain.jpg"],["Q131861",102,"compositeur","Sergueï Rachmaninov","E","Sergueï Rachmaninov, souvent désigné dans les pays francophones sous le nom de Serge Rachmaninoff, né le 1er avril 1873 à Semionov et mort le 28 mars 1943 à Beverly Hills, est un compositeur, pianiste virtuose et chef d'orchestre russe, naturalisé américain.",119,"fr:Sergueï_Rachmaninov","c:8/86/Sergei_Rachmaninoff_LOC_30160_cropped.jpg"],["Q153172",103,"compositeur","Vangelis","R","Vangelis, nom de scène d'Evángelos Odysséas Papathanassíou, né le 29 mars 1943 à Agría en Grèce et mort le 17 mai 2022 à Paris 15e, est un musicien et compositeur grec.",118,"fr:Vangelis","c:d/da/Vangelis%2C_26_July_2012.jpg"],["Q170209",104,"compositeur","Vincenzo Bellini","C","Vincenzo Bellini, né le 3 novembre 1801 à Catane, et mort le 23 septembre 1835 à Puteaux, est un compositeur italien.",null,"fr:Vincenzo_Bellini","c:5/5a/Vincenzo_bellini.jpg"],["Q14277",105,"compositeur","William Herschel","C","William Herschel est un astronome britannique d'origine allemande, également compositeur de musique. Considéré comme l'une des figures majeures de l'astronomie du XVIIIe siècle, il est surtout connu pour avoir découvert Uranus en 1781, la première planète identifiée depuis l'Antiquité. Sa contribution s'étend toutefois bien au-delà de cette découverte, puisqu'il a profondément renouvelé l'observation et la classification des objets célestes.","William Herschel est un astronome britannique d'origine allemande, également compositeur de musique.","fr:William_Herschel","c:3/36/William_Herschel01.jpg"],["Q254",106,"compositeur","Wolfgang Amadeus Mozart","M","Wolfgang Amadeus Mozart ou Johannes Chrysostomus Wolfgangus Theophilus Mozart, né le 27 janvier 1756 à Salzbourg et mort le 5 décembre 1791 à Vienne, est un compositeur germano-autrichien de la période classique. Il est considéré comme l'un des plus grands compositeurs de l'histoire de la musique. Avec Joseph Haydn et Ludwig van Beethoven, il porte à son apogée l'école classique viennoise.",115,"fr:Wolfgang_Amadeus_Mozart","c:f/ff/Mozart_%28unfinished%29_by_Lange_1782.jpg",{"cats":["classique","personnalites"]}],["Q234891",107,"compositeur","Yo-Yo Ma","R","Yo-Yo Ma, né le 7 octobre 1955 à Paris, est un violoncelliste américain d'origine chinoise.",null,"fr:Yo-Yo_Ma","c:4/42/Yo-Yo_Ma_-_Mexico_City_2019_%28cropped%29.jpg"],["Q78516",108,"interprete","Anna Netrebko","PC","Anna Iourievna Netrebko est une soprano russo-autrichienne, née le 18 septembre 1971 à Krasnodar.",null,"fr:Anna_Netrebko","c:4/4f/Anna_Netrebko_-_Romy_2013_a.jpg"],["Q3374",109,"interprete","Anne-Sophie Mutter","R","Anne-Sophie Mutter, née le 29 juin 1963 à Rheinfelden dans le Bade-Wurtemberg, est une violoniste allemande. Enfant prodige du violon, découverte par Herbert von Karajan, elle aborde avec aisance tous les répertoires de Bach à Penderecki et s'est imposée comme l'une des plus grandes violonistes de son temps.","Anne-Sophie Mutter, née le 29 juin 1963 à Rheinfelden dans le Bade-Wurtemberg, est une violoniste allemande.","fr:Anne-Sophie_Mutter","c:e/e5/Anne-Sophie_Mutter_B10-13.jpg"],["Q18828",110,"interprete","Cecilia Bartoli","C","Cecilia Bartoli, née le 4 juin 1966 à Rome, est une cantatrice mezzo-soprano italienne naturalisée autrichienne.",null,"fr:Cecilia_Bartoli","c:c/c1/Cecilia_Bartoli_at_BOZAR_2007_Cropped.jpg"],["Q152768",111,"interprete","Daniel Barenboim","PC","Daniel Barenboim ou Barenboïm, né le 15 novembre 1942 à Buenos Aires, est un pianiste et chef d'orchestre argentino-israélo-hispano-palestinien.",105,"fr:Daniel_Barenboim","c:0/07/Verleihung_Konrad-Adenauer-Preis_der_Stadt_K%C3%B6ln_2019_an_Daniel_Barenboim-9447.jpg"],["Q128967",112,"interprete","Edward Heath","R","Edward Heath, né Edward Richard George Heath le 9 juillet 1916 à Broadstairs et mort le 17 juillet 2005 à Salisbury, est un homme d'État britannique. Membre du Parti conservateur, il est Premier ministre du Royaume-Uni entre 1970 et 1974.",116,"fr:Edward_Heath","c:1/16/Edward_Heath_4_Allan_Warren.jpg"],["Q689479",113,"interprete","Gautier Capuçon","C","Gautier Capuçon, né le 3 septembre 1981 à Chambéry, est un violoncelliste français.",null,"fr:Gautier_Capuçon","c:7/7e/Gauthier_Capu%C3%A7on_2015.jpg"],["Q179277",114,"interprete","Giovanni Pierluigi da Palestrina","C","Giovanni Pierluigi da Palestrina, né à Palestrina près de Rome, vers 1525 et mort le 2 février 1594 à Rome, est un compositeur italien de la Renaissance.",114,"fr:Giovanni_Pierluigi_da_Palestrina","c:1/18/Giovanni_Pierluigi_da_Palestrina.jpg"],["Q216924",115,"interprete","Glenn Gould","PC","Glenn Gould, né le 25 septembre 1932 à Toronto et mort le 4 octobre 1982 dans la même ville, est un pianiste, compositeur, écrivain, homme de radio et réalisateur canadien.",109,"fr:Glenn_Gould","c:7/78/Glenn_Gould_1.jpg"],["Q160390",116,"interprete","Gustavo Dudamel","R","Gustavo Dudamel Ramírez, né le 26 janvier 1981 à Barquisimeto dans l'État de Lara, est un chef d'orchestre vénézuélien. En avril 2021, il est nommé directeur musical de l'Opéra de Paris, fonction dont il démissionne dès le 25 mai 2023 pour des raisons personnelles.","Gustavo Dudamel Ramírez, né le 26 janvier 1981 à Barquisimeto dans l'État de Lara, est un chef d'orchestre vénézuélien.","fr:Gustavo_Dudamel","c:a/ad/Gustavo_Dudamel.jpeg"],["Q154895",117,"interprete","Herbert von Karajan","PC","Herbert von Karajan, né le 5 avril 1908 à Salzbourg et mort le 16 juillet 1989 à Anif, près de Salzbourg, est un chef d'orchestre autrichien.",117,"fr:Herbert_von_Karajan","c:0/0f/Herbert_von_Karajan_1963_%28cropped%29.jpg"],["Q253845",118,"interprete","Hélène Grimaud","C","Hélène Grimaud, née le 7 novembre 1969 à Aix-en-Provence, est une pianiste française, également écrivaine et passionnée d'éthologie.",119,"fr:Hélène_Grimaud","c:5/53/H%C3%A9l%C3%A8ne_Grimaud_2007.jpg"],["Q215905",119,"interprete","Itzhak Perlman","R","Itzhak Perlman, né le 31 août 1945 à Tel Aviv, est un violoniste et pédagogue israélien. Il est considéré comme l'un des plus grands violonistes du XXe siècle et du XXIe siècle.","Itzhak Perlman, né le 31 août 1945 à Tel Aviv, est un violoniste et pédagogue israélien.","fr:Itzhak_Perlman","c:d/db/Itzhak_Perlman_whitehouse.jpg"],["Q228888",120,"interprete","Jacqueline du Pré","PC","Jacqueline du Pré est une violoncelliste britannique, née le 26 janvier 1945 à Oxford et morte le 19 octobre 1987 à Londres. Elle fut également la partenaire musicale et l'épouse du pianiste et chef d’orchestre israélo-palestinien-hispano-argentin Daniel Barenboim.",115,"fr:Jacqueline_du_Pré","c:8/83/Jaqueline_dupre_wedding_portrait.jpg"],["Q243472",121,"interprete","Jascha Heifetz","C","Jascha Heifetz, né le 2 février 1899 à Vilnius et mort le 10 décembre 1987 à Los Angeles, est un violoniste russe, naturalisé américain en 1925.",114,"fr:Jascha_Heifetz","c:1/16/Jascha_Heifetz_01.jpg"],["Q62358",122,"interprete","Jonas Kaufmann","C","Jonas Kaufmann est un ténor allemand né le 10 juillet 1969 à Munich.",null,"fr:Jonas_Kaufmann","c:4/4f/%D0%9A%D0%B0%D1%83%D1%84%D0%BC%D0%B0%D0%BD_%D0%B8%D0%BA%D0%BE%D0%BD%D0%BA%D0%B0.jpg"],["Q485165",123,"interprete","José Carreras","PC","José Carreras est un artiste lyrique espagnol, né le 5 décembre 1946 à Barcelone. Réputé pour ses interprétations d'œuvres de Donizetti, Verdi et Puccini, il a notamment participé aux concerts des Trois Ténors, aux côtés de Plácido Domingo et de Luciano Pavarotti.","José Carreras est un artiste lyrique espagnol, né le 5 décembre 1946 à Barcelone.","fr:José_Carreras","c:b/b3/Jose_Carreras_Royal_Albert_Hall_2001.jpg"],["Q467436",124,"interprete","Khatia Buniatishvili","PC","Khatia Buniatishvili ou Buniatichvili, née le 21 juin 1987 à Batoumi, est une pianiste géorgienne, naturalisée française en 2017.",110,"fr:Khatia_Buniatishvili","c:3/3f/Khatia_Buniatishvili_-_Global_Citizen_Festival_Hamburg_13.jpg"],["Q50806463",125,"interprete","Klaus Mäkelä","PC","Klaus Mäkelä, né le 17 janvier 1996 à Helsinki, est un chef d'orchestre et violoncelliste finlandais.",null,"fr:Klaus_Mäkelä","c:0/04/KlausMakela2022.jpg"],["Q155713",126,"interprete","Lang Lang","R","Lang Lang, né le 14 juin 1982 à Shenyang, est un pianiste chinois.",null,"fr:Lang_Lang","c:9/90/World-renowned_pianist_Lang_Lang.jpg"],["Q128297",127,"interprete","Maria Callas","L","Maria Callas est une cantatrice grecque née le 2 décembre 1923 à New York et morte le 16 septembre 1977 à Paris.",null,"fr:Maria_Callas","c:a/a1/Maria_Callas_1958.jpg"],["Q156810",128,"interprete","Martha Argerich","R","Martha Argerich, née le 5 juin 1941 à Buenos Aires, est une pianiste suisso-argentine, considérée comme l'une des plus grandes interprètes de sa génération, voire de l'histoire.",118,"fr:Martha_Argerich","c:9/95/Martha_argerich_photo_%28cropped%29.jpg"],["Q151435",129,"interprete","Montserrat Caballé","PC","Montserrat Caballé est une cantatrice espagnole née le 12 avril 1933 à Barcelone et morte le 6 octobre 2018 dans la même ville.",115,"fr:Montserrat_Caballé","c:f/f5/Montserrat_Caball%C3%A9_c._1969_%281%29.jpg"],["Q140619",130,"interprete","Nadia Boulanger","C","Nadia Boulanger, née le 16 septembre 1887 dans le 9e arrondissement de Paris, où elle est morte le 22 octobre 1979, est une pédagogue, pianiste, organiste, cheffe de chœur, cheffe d'orchestre et compositrice française. Elle est la sœur aînée de la compositrice Lili Boulanger.",119,"fr:Nadia_Boulanger","c:c/c1/Nadia_Boulanger_1925.jpg"],["Q130853",131,"interprete","Plácido Domingo","R","José Plácido Domingo Embil, plus connu sous le nom de Plácido Domingo, est un chanteur d'opéra, chef d'orchestre et administrateur d'opéra espagnol, né le 21 janvier 1941 à Madrid en Espagne.",115,"fr:Plácido_Domingo","c:0/02/Pl%C3%A1cido_Domingo%2C_2008.jpg"],["Q103774",132,"interprete","Ravi Shankar","E","Robendra Shankar dit Ravi Shankar, né le 7 avril 1920 à Bénarès, situé alors dans les Indes britanniques, et mort le 11 décembre 2012 à San Diego, est un musicien sitariste et compositeur indien, de notoriété internationale depuis les années 1960. Son nom est souvent précédé du titre honorifique de pandit.",119,"fr:Ravi_Shankar","c:8/83/Ravi_Shankar_2009.jpg"],["Q552845",133,"interprete","Renaud Capuçon","C","Renaud Capuçon, né le 27 janvier 1976 à Chambéry, est un violoniste et chef d'orchestre français.",null,"fr:Renaud_Capuçon","c:f/f1/Renaud_Capu%C3%A7on_2013.jpg"],["Q165637",134,"interprete","Renée Fleming","C","Renée Fleming est une soprano américaine, née le 14 février 1959 à Indiana.",null,"fr:Renée_Fleming","c:e/e6/Ren%C3%A9e_Fleming_became_a_46th_Kennedy_Center_honoree_on_December_3%2C_2023_in_the_White_House_Oval_Office_%28cropped%29.jpg"],["Q276038",135,"interprete","Riccardo Muti","C","Riccardo Muti, né le 28 juillet 1941 à Naples, est un chef d'orchestre italien.",null,"fr:Riccardo_Muti","c:9/9f/Embajador_Wayne_asiste_a_la_clase_magistral_impartida_por_el_Maestro_Riccardo_Muti_%28cropped%29.jpg"],["Q267617",136,"interprete","Roberto Alagna","PC","Roberto Francesco Alagna, ou plus simplement Roberto Alagna, né le 7 juin 1963 à Clichy-sous-Bois, est un ténor franco-italien.",111,"fr:Roberto_Alagna","c:c/cc/ALAGNA-24x30-2004.jpg"],["Q157814",137,"interprete","Simon Rattle","C","Simon Rattle, né le 19 janvier 1955 à Liverpool, est un chef d'orchestre britannique.",null,"fr:Simon_Rattle","c:4/45/Rattle_BPH-Rittershaus2-_Wikipedia.jpg"],["Q192506",138,"interprete","Vladimir Horowitz","PC","Vladimir Samoïlovitch Horowitz, né à Berditchev ou à Kiev, le 1er octobre 1903 et mort à New York le 5 novembre 1989, est un pianiste d'origine ukrainienne, naturalisé américain. Il fait partie des plus grands virtuoses de l'histoire du piano.",117,"fr:Vladimir_Horowitz","c:7/70/Vladimir_Horowitz_C37292-1_%28cropped%29.jpg"],["Q156814",139,"interprete","Yehudi Menuhin","C","Yehudi Menuhin est un violoniste et chef d'orchestre britannique et suisse d'origine américaine, né le 22 avril 1916 à New York et mort le 12 mars 1999 à Berlin. Il est un enfant prodige, se produisant dès 1927 à Paris avec l'Orchestre Lamoureux et à New York au Carnegie Hall. Il est considéré comme l'un des plus grands violonistes du XXe siècle.",118,"fr:Yehudi_Menuhin","c:b/be/Yehudi_Menuhin_1976.jpg"],["Q465311",140,"interprete","Yuja Wang","E","Yuja Wang, née le 10 février 1987 à Pékin, est une pianiste classique sino-américaine.",null,"fr:Yuja_Wang","c:9/9f/Yuja-Wang-2014.jpg"],["Q346715",141,"oeuvre","Adagio pour cordes","C","L'Adagio pour cordes est une œuvre musicale pour orchestre à cordes en si bémol mineur, arrangée en 1936 par le compositeur Samuel Barber à partir de son premier quatuor à cordes créé la même année. C'est l'œuvre la plus connue de Barber.",111,"fr:Adagio_pour_cordes","c:9/91/Samuel_Barber.jpg"],["Q35720",142,"oeuvre","Ainsi parlait Zarathoustra","C","Ainsi parlait Zarathoustra op. 30 est un poème symphonique composé par Richard Strauss entre février et août 1896, librement inspiré du poème philosophique Ainsi parlait Zarathoustra du philosophe allemand Friedrich Nietzsche. La première a lieu à Francfort le 27 novembre 1896 sous la direction du compositeur. Son introduction grandiose est rendue célèbre par sa reprise dans la musique de film de science-fiction culte 2001, l'Odyssée de l'espace de Stanley Kubrick et de la Metro-Goldwyn-Mayer en 1968.","Ainsi parlait Zarathoustra op.","fr:Ainsi_parlait_Zarathoustra_(Strauss)","c:b/b0/Strauss_conducting.jpg"],["Q935151",143,"oeuvre","Air sur la corde de sol","C","L’Air sur la corde de sol est un arrangement, une réduction et une transposition, de l'air, deuxième mouvement de la suite orchestrale no 3 en ré majeur BWV 1068 de Jean-Sébastien Bach.",116,"fr:Air_sur_la_corde_de_sol","c:c/ce/August_Wilhelmj.jpg"],["Q1331995",144,"oeuvre","Ave Maria","C","Ellens dritter Gesang, littéralement le « Troisième chant d'Ellen », est une des compositions les plus populaires de Franz Schubert. Composée en 1825, elle est aujourd'hui mondialement connue sous le nom d'« Ave Maria de Schubert ».",116,"fr:Ave_Maria_(Schubert)","c:0/0d/Franz_Schubert_c1827.jpg"],["Q327331",145,"oeuvre","Boléro","PC","Le Boléro de Maurice Ravel est une musique de ballet pour orchestre en ut majeur composée en 1928 et créée le 22 novembre de la même année à l’Opéra Garnier par sa dédicataire, la danseuse russe Ida Rubinstein. Mouvement de danse au rythme et au tempo invariables, à la mélodie uniforme et répétitive, le Boléro de Ravel tire ses seuls éléments de variation des effets d’orchestration, d’un crescendo graduel et, in extremis, d’une courte modulation en mi majeur.",112,"fr:Boléro_(Ravel)","c:5/51/Bol%C3%A9ro_de_Ravel%2C_Orchestre_de_l%27Association_des_Concerts_Lamoureux%2C_1935.jpg"],["Q253716",146,"oeuvre","Carmina Burana","PC","Les Carmina Burana sont une cantate scénique composée par Carl Orff en 1935-1936. Le titre complet, en latin, est « Carmina Burana: Cantiones profanæ, cantoribus et choris cantandæ, comitantibus instrumentis atque imaginibus magicis », soit en français: Poèmes chantés de Beuern: Chants profanes, pour chanteurs solistes et chœurs, avec accompagnement instrumental et images magiques.","Les Carmina Burana sont une cantate scénique composée par Carl Orff en 1935-1936.","fr:Carmina_Burana_(cantate)","c:7/7d/Wheel-of-fortune-carmina-burana.jpg"],["Q193705",147,"oeuvre","Casse-Noisette","E","Casse-Noisette est un ballet-féerie dont la musique est de Piotr Ilitch Tchaïkovski en deux actes, soit trois tableaux et 15 scènes, présenté pour la première fois le 18 décembre 1892 au théâtre Mariinsky de Saint-Pétersbourg sous la direction de Riccardo Drigo et chorégraphié par Lev Ivanov.",118,"fr:Casse-Noisette","c:b/be/Snowdance.jpg"],["Q26473",148,"oeuvre","Chant grégorien","PC","Le chant grégorien est le chant liturgique officiel et ordinaire de l'Église catholique. Issu du chant vieux-romain et du chant gallican, il reste pratiqué de nos jours dans un certain nombre d'églises paroissiales, de monastères ainsi que par des musiciens professionnels.","Le chant grégorien est le chant liturgique officiel et ordinaire de l'Église catholique.","fr:Chant_grégorien","c:b/be/121_Initiale_P.jpg"],["Q1464243",149,"oeuvre","Chevauchée des Walkyries","C","La chevauchée des Walkyries est un célèbre extrait de l'opéra La Walkyrie, second opéra de la Tétralogie de Richard Wagner. Correspondant à la fois au prélude et au premier air du dernier acte, il est baptisé du nom des Valkyries guerrières des mythologies germanique et nordique. Remarquée pour sa dimension épique, exaltée, grandiose et tragique à la fois, cette chevauchée est à la fois l'un des morceaux les plus célèbres de la Tétralogie et de l'œuvre de Richard Wagner, voire du répertoire de la musique savante.",115,"fr:Chevauchée_des_Walkyries","c:9/9d/RichardWagner.jpg"],["Q210224",150,"oeuvre","Concerto pour piano no 2 de Rachmaninov","C","Le Concerto pour piano no 2 en do mineur, op. 18, est un concerto du compositeur russe Sergueï Rachmaninov, écrit dans les années 1900 et 1901, quelque peu avant la composition de sa Sonate pour violoncelle et piano.","Le Concerto pour piano no 2 en do mineur, op.","fr:Concerto_pour_piano_no_2_de_Rachmaninov","c:2/2f/Ci%C4%85gli%C5%84ski_Portret_Rachmaninowa_1900.jpg"],["Q208224",151,"oeuvre","Concertos brandebourgeois","C","Les concertos brandebourgeois sont un ensemble de six concertos de Johann Sebastian Bach réunis en 1721, et qui comptent parmi les plus renommés qu'il ait composés. Le qualificatif « brandebourgeois » est dû au musicologue Philipp Spitta, biographe de Bach en 1873, qui, suivant l'usage germanique, fait référence au dédicataire, le margrave Christian-Louis de Brandebourg-Schwedt.",111,"fr:Concertos_brandebourgeois","c:b/b0/Title_page_of_Brandenburg_Concertos.png"],["Q956115",152,"oeuvre","Dans l'antre du roi de la montagne","PC","Dans l'antre du roi de la montagne est un extrait de la musique de scène, no 1 de l'op. 46, qu'Edvard Grieg composa en 1874 pour la pièce de théâtre Peer Gynt, écrite par l'auteur norvégien Henrik Ibsen en 1867, et jouée pour la première fois à Christiania le 24 février 1876. Le compositeur sélectionnera plus tard cette pièce en si mineur, notée 4/4, Alla marcia e molto marcato, puis più vivo et enfin stringendo al fine, pour constituer le mouvement final de la première de deux suites, op.","Dans l'antre du roi de la montagne est un extrait de la musique de scène, no 1 de l'op.","fr:Dans_l'antre_du_roi_de_la_montagne","c:9/99/%28Edvard_Grieg_portrait%29_%283469853267%29.jpg"],["Q1164860",153,"oeuvre","Danse macabre","C","La Danse macabre, opus 40, est un poème symphonique en sol mineur composé en 1874 par Camille Saint-Saëns d'après le poème d'Henri Cazalis Égalité-Fraternité, tiré des Heures sombres, quatrième partie de son recueil L'Illusion paru en 1875. Elle est jouée pour la première fois à Paris le 24 janvier 1875, sous la direction d'Édouard Colonne. Contrairement à la légende, la Danse macabre n'a été ni chahutée ni sifflée à la première de Colonne, ni à la seconde audition, le 7 février 1875. Colonne dut même la bisser.",116,"fr:Danse_macabre_(Saint-Saëns)","c:f/f1/Danse_macabre_%28manuscrit_autographe%29_-_btv1b550084340_%2807_of_63%29.jpg"],["Q83771",154,"oeuvre","Dies iræ","R","Le Dies iræ, aussi appelé Prose des Morts, est une séquence (ou prose) médiévale chantée, adoptant la forme d'une hymne liturgique. L'inspiration du poème est partiellement apocalyptique. Les prémices de cette séquence sont apparues dès le début du XIe siècle, la version actuelle datant du XIIIe siècle.",113,"fr:Dies_iræ","c:0/03/MemlingJudgmentCentre.jpg"],["Q1190965",155,"oeuvre","Gymnopédies","PC","Les Gymnopédies ou Trois Gymnopédies sont une série de trois variantes de valses lentes impressionnistes pour piano solo, composées par Erik Satie et publiées en 1888 à Paris. Elles sont inspirées du roman historique Salammbô de Gustave Flaubert et des Gymnopédies, danses rituelles exécutées à Sparte lors de fêtes religieuses du temps de la Grèce antique. Elles sont parmi ses compositions les plus célèbres avec les Gnossiennes.",115,"fr:Gymnopédies_(Satie)","c:c/cc/Gymnop%C3%A9die_1_d%27Erik_Satie%2C_autographe.jpg"],["Q844790",156,"oeuvre","L'Oiseau de feu","C","L'Oiseau de feu est un ballet en deux tableaux d'après un conte national russe. La musique a été composée par Igor Stravinsky en 1909-1910 sur la commande de Serge de Diaghilev. Il a été créé à l'Opéra de Paris le 25 juin 1910 par les Ballets russes sur une chorégraphie de Michel Fokine et sous la direction de Gabriel Pierné.","L'Oiseau de feu est un ballet en deux tableaux d'après un conte national russe.","fr:L'Oiseau_de_feu","c:d/d7/L%27Oiseau_de_feu_by_A._Golovin_01.jpg"],["Q838051",157,"oeuvre","La Belle au bois dormant","C","La Belle au bois dormant est un ballet en un prologue, trois actes et cinq tableaux représenté pour la première fois le 15 janvier 1890 au Théâtre Mariinsky de Saint-Pétersbourg, avec une chorégraphie de Marius Petipa et sur une musique de Piotr Ilitch Tchaïkovski, inspiré du conte de Charles Perrault et des frères Grimm.",119,"fr:La_Belle_au_bois_dormant_(ballet)","c:a/a9/Sleeping_beauty_cast.jpg"],["Q11980",158,"oeuvre","La Lettre à Élise","PC","La Bagatelle en la mineur, WoO 59, « La Lettre à Élise » est une pièce musicale pour piano en la mineur composée par Ludwig van Beethoven en 1810.",116,"fr:La_Lettre_à_Élise","c:a/a3/Beethovenhome.JPG"],["Q1617048",159,"oeuvre","Lacrimosa","C","Le Dies iræ, aussi appelé Prose des Morts, est une séquence médiévale chantée, adoptant la forme d'une hymne liturgique. L'inspiration du poème est partiellement apocalyptique. Les prémices de cette séquence sont apparues dès le début du XIe siècle, la version actuelle datant du XIIIe siècle. C'est à cette époque et sous cet aspect qu'elle a été intégrée au corpus grégorien. Le Dies iræ a ensuite été chanté pendant des siècles dans la messe de Requiem.","Le Dies iræ, aussi appelé Prose des Morts, est une séquence médiévale chantée, adoptant la forme d'une hymne liturgique.","fr:Lacrimosa_(requiem)","c:1/15/Weyden_michael.jpg"],["Q482621",160,"oeuvre","Le Beau Danube bleu","C","Le Beau Danube bleu op. 314, est une célèbre valse viennoise pour orchestre symphonique, composée par le compositeur autrichien Johann Strauss II en 1866. Poème symphonique dédié au Danube, elle fait partie de ses œuvres les plus célèbres, avec entre autres Wiener Blut de 1873, régulièrement jouées entre autres par l'Orchestre philharmonique de Vienne en clôture et un des rappels traditionnels du concert du nouvel an à Vienne.","Le Beau Danube bleu op.","fr:Le_Beau_Danube_bleu","c:5/54/Johann_Strauss_%28figlio%29_II.jpg"],["Q941724",161,"oeuvre","Le Carnaval des animaux","PC","Le Carnaval des animaux est une suite pour ensemble instrumental de Camille Saint-Saëns composée en Autriche au début de 1886. L'œuvre est créée le 9 mars 1886 puis jouée le 2 avril 1886 en auditions privées à Paris, chez le violoncelliste Charles Lebouc et chez la cantatrice Pauline Viardot respectivement. Les premières auditions intégrales, publiques, ont lieu le 25 et le 26 février 1922 sous la direction de Gabriel Pierné.",117,"fr:Le_Carnaval_des_animaux","c:f/f7/Le_carnaval_des_animaux_de_Saint-Sa%C3%ABns_%C3%A9dition.jpg"],["Q211971",162,"oeuvre","Le Clavier bien tempéré","C","Le Clavier bien tempéré, couvrant les numéros BWV 846 à 893, est un ensemble de deux cycles de vingt-quatre couples prélude et fugue chacun, composé par Jean-Sébastien Bach. Ces deux recueils sont l'une des œuvres les plus importantes de l'histoire de la musique classique. Leur objectif est à la fois musical, théorique et didactique.",115,"fr:Le_Clavier_bien_tempéré","c:3/34/WTK-I-12-02.jpg"],["Q199786",163,"oeuvre","Le Lac des cygnes","E","Le Lac des cygnes, op. 20 est un ballet en quatre actes sur une musique de Piotr Ilitch Tchaïkovski et un livret de Vladimir Begitchev inspiré d'une légende allemande. Il est composé entre 1875 et 1876.","Le Lac des cygnes, op.","fr:Le_Lac_des_cygnes","c:9/97/Yuka_Ebihara_%28Odetta%29%2C_Jezioro_%C5%82ab%C4%99dzie%2C_Polski_Balet_Narodowy%2C_choreografia_Krzysztof_Pastor_wg_Lwa_Iwanowa%2C_fot._Ewa_Krasucka_TW-ON.jpg"],["Q206015",164,"oeuvre","Le Sacre du printemps","PC","Le Sacre du printemps, sous-titré Tableaux de la Russie païenne en deux parties, est un ballet composé par Igor Stravinsky et chorégraphié originellement par Vaslav Nijinski pour les Ballets russes de Serge de Diaghilev.",111,"fr:Le_Sacre_du_printemps","c:6/62/Roerich_Rite_of_Spring.jpg"],["Q1342275",165,"oeuvre","Le Vol du bourdon","C","Le Vol du bourdon est un interlude orchestral écrit en 1899-1900 par Nikolaï Rimski-Korsakov pour son opéra Le Conte du tsar Saltan.",119,"fr:Le_Vol_du_bourdon","c:7/79/Flight_of_the_Bumblebee_on_Pipe_Organ_Pedals.webm"],["Q303508",166,"oeuvre","Les Planètes","PC","The Planets, également connue sous le titre francisé Les Planètes, est un poème symphonique de Gustav Holst composé entre 1914 et 1917. Œuvre pour grand orchestre, elle se compose de sept mouvements correspondant chacun à une planète du système solaire, exprimée selon une vision astrologique: Mercure, Vénus, Mars, Jupiter, Saturne, Uranus et Neptune. C'est en grande partie à cette pièce que Holst doit sa notoriété.",115,"fr:Les_Planètes","c:8/83/Solar_system.jpg"],["Q12016",167,"oeuvre","Les Quatre Saisons","R","Les Quatre Saisons d'Antonio Vivaldi sont les quatre premiers concertos baroques des douze concertos pour violon intitulés « Il cimento dell'armonia e dell'inventione », composés le 17 juin 1724 et publiés en 1725 à Amsterdam par Michel Le Cène. Leur première interprétation publique a lieu notamment à Londres et au Concert Spirituel de Paris du début de l’année 1728.",112,"fr:Les_Quatre_Saisons","c:9/98/Antonio_Vivaldi_portrait.jpg"],["Q12001",168,"oeuvre","Marche de Radetzky","C","Marche de Radetzky est une célèbre marche militaire viennoise de Johann Strauss père composée en 1848 en l'honneur du Feld-maréchal autrichien Joseph Radetzky von Radetz, vainqueur de la bataille de Custoza contre les Piémontais en 1848, mais aussi fer de lance de la réaction qui suit le Printemps des peuples et met en place le Système de Bach auprès du jeune empereur François-Joseph Ier d'Autriche.",117,"fr:Marche_de_Radetzky","c:6/6e/Radetzky-von-radetz.jpg"],["Q207732",169,"oeuvre","Messiah","PC","Le Messie est un oratorio pour chœur, solistes vocaux et orchestre, composé en 1741 par Georg Friedrich Haendel. C'est une de ses œuvres les plus populaires avec les suites orchestrales Water Music et Music for the Royal Fireworks. Le Messie est désormais considéré comme le chef-d'œuvre du genre oratorio. Son exécution dure environ 2 heures 30 minutes.","Le Messie est un oratorio pour chœur, solistes vocaux et orchestre, composé en 1741 par Georg Friedrich Haendel.","fr:Messiah","c:7/71/Messiah-titlepage.jpg"],["Q769763",170,"oeuvre","Nocturnes de Chopin","C","Les Nocturnes de Chopin sont vingt-et-un morceaux de musique romantique pour piano seul composés par Frédéric Chopin entre 1827 et 1846. Ils tiennent une place importante dans le répertoire de concert contemporain. Bien que Chopin n'ait pas inventé le nocturne, il a popularisé le genre et l'a répandu, à partir de la forme développée par le compositeur irlandais John Field.",116,"fr:Nocturnes_de_Chopin","c:9/94/Op.27_Nocturne.jpg"],["Q597353",171,"oeuvre","O Fortuna","C","O Fortuna ou Fortuna Imperatrix Mundi est un poème-chant-manuscrit bavarois médiéval du XIIIe siècle, sur le thème de « la fortune » extrait du codex Carmina Burana recueil de 315 poèmes médiévaux goliards, de l'abbaye de Benediktbeuern en Bavière en Allemagne, où ils sont découverts en 1803. Il est rendu célèbre par sa mise en musique de la cantate Carmina Burana de 1936, du compositeur bavarois Carl Orff.",119,"fr:O_Fortuna","c:4/43/CarminaBurana_wheel.jpg",{"cats":["classique","livres"]}],["Q41545",172,"oeuvre","Ode à la joie","R","Ode à la joie — appelée également Hymne à la joie — est un poème de Friedrich von Schiller écrit en 1785. Il est surtout connu comme finale du quatrième et dernier mouvement de la 9e Symphonie de Beethoven, devenu l'hymne officiel de l'Union européenne et du Conseil de l'Europe.","Ode à la joie — appelée également Hymne à la joie — est un poème de Friedrich von Schiller écrit en 1785.","fr:Ode_à_la_joie","c:2/2d/Schiller_an_die_freude_manuskript_2.jpg"],["Q6046246",173,"oeuvre","Ouverture de Guillaume Tell","C","L'ouverture de Guillaume Tell est l'ouverture de l'opéra de Gioachino Rossini, Guillaume Tell.",null,"fr:Ouverture_de_Guillaume_Tell","c:6/68/Gioachino_Rossini%2C_1828%2C_by_Hortense_Haudebourt-Lescot.jpg"],["Q212776",174,"oeuvre","Ouverture solennelle 1812","PC","L’Ouverture solennelle 1812 en mi bémol majeur, op. 49, également appelée L'Année 1812 ou Ouverture 1812, est une ouverture solennelle de Piotr Ilitch Tchaïkovski, composée entre septembre et novembre 1880 pour commémorer la retraite de Russie lors de la campagne napoléonienne de Russie en 1812.","L’Ouverture solennelle 1812 en mi bémol majeur, op.","fr:Ouverture_solennelle_1812","c:1/1e/Peter_Tschaikowski.jpg"],["Q379111",175,"oeuvre","Passion selon saint Matthieu","C","La Passion selon saint Matthieu est un oratorio de Bach exécuté probablement pour la première fois le vendredi saint 1727. L'œuvre a été remaniée trois fois. La troisième version, définitive, a été créée en 1736.",116,"fr:Passion_selon_saint_Matthieu","c:a/a6/Jsbwv244.jpg"],["Q14912776",176,"oeuvre","Peer Gynt","C","Peer Gynt est la musique de scène composée par Edvard Grieg en 1875 pour la pièce d'Henrik Ibsen. On lui doit notamment les célèbres « Au matin » et « Dans l'antre du roi de la montagne ».","","en:Peer_Gynt_(Grieg)","c:c/c0/Edvard_Grieg_%281888%29_by_Elliot_and_Fry_-_02.jpg"],["Q677403",177,"oeuvre","Pierre et le Loup","PC","Pierre et le Loup opus 67, est un conte symphonique didactique, pédagogique, allégorique pour enfants, de l'auteur-compositeur-interprète russe Sergueï Prokofiev.",105,"fr:Pierre_et_le_Loup","c:5/55/Sergei_Prokofiev_03.jpg"],["Q1141118",178,"oeuvre","Pomp and Circumstance","C","Pomp and Circumstance Military Marches, op. 39 est une série de cinq marches pour orchestre composée par Edward Elgar entre 1901 et 1930.","Pomp and Circumstance Military Marches, op.","fr:Pomp_and_Circumstance","c:3/35/Sir_Edward_Elgar_1904.jpeg"],["Q1811459",179,"oeuvre","Requiem de Fauré","C","La Messe de requiem en ré mineur op. 48 de Gabriel Fauré, écrite en pleine maturité de ce compositeur, est l'une de ses œuvres les plus connues.","La Messe de requiem en ré mineur op.","fr:Requiem_(Fauré)","c:5/51/Faure_Requiem_Manuscript.gif"],["Q207875",180,"oeuvre","Requiem de Mozart","R","La messe de Requiem en ré mineur, de Wolfgang Amadeus Mozart, composée en 1791, est une œuvre de la dernière année de la vie de Mozart, mais pas exactement la dernière œuvre du compositeur. Elle n'est de la main de Mozart que pour les deux tiers environ, la mort en ayant interrompu la composition. Elle reste néanmoins une de ses œuvres majeures et emblématiques.",117,"fr:Requiem_(Mozart)","c:1/1e/Wolfgang-amadeus-mozart_1.jpg"],["Q1356210",181,"oeuvre","Requiem de Verdi","C","La Messa da requiem de Giuseppe Verdi est une messe de requiem pour solistes, double chœur et orchestre, créée le 22 mai 1874.",116,"fr:Requiem_(Verdi)","c:e/e2/Verdi_Requiem_poster_1874.jpg"],["Q722599",182,"oeuvre","Rhapsody in Blue","C","Rhapsody in Blue est une œuvre pour piano et orchestre ou harmonie composée par George Gershwin en 1924, qui combine des éléments de musique classique et de jazz.",116,"fr:Rhapsody_in_Blue","c:d/d4/Rhapsody_in_Blue_cover.jpg"],["Q911487",183,"oeuvre","Roméo et Juliette","C","Roméo et Juliette, op. 64, est un ballet en trois actes de Sergueï Prokofiev, composé en 1935 peu après le retour du compositeur en Union soviétique. Il est fondé sur la pièce éponyme de William Shakespeare.","Roméo et Juliette, op.","fr:Roméo_et_Juliette_(ballet)","c:4/48/RR5115-0025R_225-%D0%BB%D0%B5%D1%82%D0%B8%D0%B5_%D0%91%D0%BE%D0%BB%D1%8C%D1%88%D0%BE%D0%B3%D0%BE_%D1%82%D0%B5%D0%B0%D1%82%D1%80%D0%B0.gif"],["Q171405",184,"oeuvre","Schéhérazade","C","Schéhérazade, op. 35, est une suite symphonique de Nikolaï Rimski-Korsakov créée à Saint-Pétersbourg le 3 novembre 1888 dans le cadre des Concerts symphoniques russes. L'œuvre étant constituée de quatre mouvements, on peut la considérer comme une grande symphonie classique et cependant centrée sur un programme particulier, comme le sont la 6e symphonie de Beethoven et la Symphonie fantastique de Berlioz, même si ces deux dernières sont constituées, non pas de quatre, mais de cinq mouvements.","Schéhérazade, op.","fr:Schéhérazade_(Rimski-Korsakov)","c:1/17/Scheherazade_de_Rimski-Korsakov.jpg"],["Q12008",185,"oeuvre","Sonate pour piano no 14 de Beethoven","C","La Sonate pour piano no 14 de Beethoven en do dièse mineur, opus 27 no 2, surnommée « Sonate au Clair de lune », est une sonate pour piano seul en trois mouvements composée par Ludwig van Beethoven en 1801.",116,"fr:Sonate_pour_piano_no_14_de_Beethoven","c:1/11/Beethoven_Piano_Sonata_14_-_title_page_1802.jpg"],["Q1367599",186,"oeuvre","Suite bergamasque","C","La Suite bergamasque est une suite pour piano du compositeur français Claude Debussy, dont la première rédaction remonte à 1890 environ, et qui est publiée en juin 1905.",112,"fr:Suite_bergamasque","c:7/77/Bergamo_Notturno_Porta_San_Giacomo.jpg"],["Q462313",187,"oeuvre","Symphonie fantastique","C","La Symphonie fantastique, op. 14, est une œuvre d'Hector Berlioz, dédiée à Nicolas Ier de Russie et créée à Paris le 5 décembre 1830 à la salle du Conservatoire, sous la direction de François-Antoine Habeneck, six ans après la neuvième symphonie de Beethoven. Composée de cinq scènes descriptives, cette œuvre, plus proche du poème symphonique que de la symphonie, est qualifiée de musique à programme.","La Symphonie fantastique, op.","fr:Symphonie_fantastique","c:2/26/Symphonie_Fantastique.png"],["Q157489",188,"oeuvre","Symphonie no 3 de Beethoven","C","La Symphonie no 3 en mi bémol majeur communément appelée Eroica op. 55 de Ludwig van Beethoven est la troisième de ses neuf symphonies, composée en 1803 – 1804 et créée publiquement le 7 avril 1805 au Theater an der Wien à Vienne, avec Franz Clement comme Konzertmeister. Une première audition privée s'est vraisemblablement tenue le 9 juin 1804 dans le palais viennois du prince Joseph Franz von Lobkowitz, selon ce qu'attestent les registres de son Kapellmeister Anton Wranitzky.","La Symphonie no 3 en mi bémol majeur communément appelée Eroica op.","fr:Symphonie_no_3_de_Beethoven","c:0/09/Eroica_Beethoven_title.jpg"],["Q188709",189,"oeuvre","Symphonie no 5 de Beethoven","C","La Symphonie no 5 en ut mineur, op. 67, dite Symphonie du Destin, a été écrite par Ludwig van Beethoven en 1805-1807 et créée le 22 décembre 1808 au Theater an der Wien de Vienne. Le compositeur a dédié l'œuvre au prince Lobkowitz et au comte Razoumovski, un diplomate russe qui avait commandé les trois quatuors à cordes de l'op. 59 à Beethoven.","La Symphonie no 5 en ut mineur, op.","fr:Symphonie_no_5_de_Beethoven","c:6/6a/Beethoven-Deckblatt.png"],["Q240240",190,"oeuvre","Symphonie no 5 de Mahler","C","La Symphonie no 5 en do dièse mineur de Gustav Mahler a été composée entre 1901 et 1902. Elle est contemporaine notamment de 3 des Kindertotenlieder et partage le même caractère funèbre, peut-être en rapport avec les graves problèmes de santé du musicien. La partition fut ensuite révisée à plusieurs reprises, la dernière étant de 1911. La première eut lieu cependant à Cologne le 18 octobre 1904 avec un succès très mitigé.","La Symphonie no 5 en do dièse mineur de Gustav Mahler a été composée entre 1901 et 1902.","fr:Symphonie_no_5_de_Mahler","c:0/03/Emil_Orlik_Gustav_Mahler_1902.jpg"],["Q246433",191,"oeuvre","Symphonie no 6 de Beethoven","C","La Symphonie no 6 en fa majeur, opus 68, dite Pastorale, de Ludwig van Beethoven, est composée entre 1805 et 1808. Beethoven l'intitule précisément dans une lettre à Breitkopf & Härtel: Symphonie Pastorale, ou Souvenir de la vie rustique, plutôt émotion exprimée que peinture descriptive et la co-dédie au prince Lobkowitz et au comte Razumovsky. L'œuvre est créée le 22 décembre 1808 au Theater an der Wien de Vienne et publiée en avril 1809 chez Breitkopf & Härtel, jouée et publiée en même temps que la cinquième.","La Symphonie no 6 en fa majeur, opus 68, dite Pastorale, de Ludwig van Beethoven, est composée entre 1805 et 1808.","fr:Symphonie_no_6_de_Beethoven","c:0/0e/Beethoven_Hornemann.jpg"],["Q11989",192,"oeuvre","Symphonie no 9 de Beethoven","PC","La Symphonie no 9, op. 125, de Ludwig van Beethoven, est une symphonie chorale en ré mineur en quatre mouvements pour grand orchestre, solos et chœur mixte. Elle a été composée de la fin de l'année 1822 à février 1824, et créée à Vienne le 7 mai 1824 en hommage au roi Frédéric-Guillaume III de Prusse. Son finale est à lui seul aussi long que la totalité de la Huitième symphonie; il introduit des sections chantées sur l'Ode à la joie de Friedrich von Schiller.","La Symphonie no 9, op.","fr:Symphonie_no_9_de_Beethoven","c:5/56/Beethoven_Ninth_Symphony.png"],["Q11985",193,"oeuvre","Symphonie no 9 de Dvořák","C","La Symphonie no 9 en mi mineur, B. 178 « Du Nouveau Monde » est composée par Antonín Dvořák en 1893 et exécutée le 16 décembre de la même année au Carnegie Hall par l'Orchestre philharmonique de New York sous la direction d'Anton Seidl. Elle est la plus connue des symphonies de Dvořák et l'une des œuvres les plus populaires du répertoire symphonique moderne.","La Symphonie no 9 en mi mineur, B.","fr:Symphonie_no_9_de_Dvořák","c:f/ff/The_title_page_of_the_autograph_score_of_Dvo%C5%99%C3%A1k%27s_ninth_symphony.jpg"],["Q724981",194,"oeuvre","Tableaux d'une exposition","PC","Tableaux d'une exposition, est une « série de dix pièces pour piano » entrecoupées de « promenades », composée par Modeste Moussorgski en juin et juillet 1874. L'œuvre est dédiée à Viktor Hartmann.",114,"fr:Tableaux_d'une_exposition","c:d/d5/Pictures_at_the_Exhibition_1st_edition.jpg"],["Q392734",195,"oeuvre","Toccata et fugue en ré mineur","PC","La Toccata et fugue en ré mineur, BWV 565, est une œuvre pour orgue écrite par Jean-Sébastien Bach entre 1703 et 1707.",null,"fr:Toccata_et_fugue_en_ré_mineur","https://upload.wikimedia.org/wikipedia/commons/thumb/1/14/Toccata-Fugue-BWV565_Bach-intro.svg/330px-Toccata-Fugue-BWV565_Bach-intro.svg.png"],["Q285976",196,"oeuvre","Une nuit sur le mont Chauve","C","Une nuit sur le mont Chauve est un poème symphonique composé par Modeste Moussorgski en 1867. Inspiré par des œuvres littéraires et des légendes russes, Moussorgski composa un « tableau musical », littéralement La nuit de la Saint-Jean sur le mont Chauve, sur le thème d'un sabbat de sorcières se déroulant sur le mont Chauve la veille de la Saint-Jean, qu'il acheva cette même nuit, le 23 juin 1867. Avec Sadko op.","Une nuit sur le mont Chauve est un poème symphonique composé par Modeste Moussorgski en 1867.","fr:Une_nuit_sur_le_mont_Chauve","c:8/8b/Musorgskiy_in_1865b.jpg"],["Q12025",197,"oeuvre","Une petite musique de nuit","C","La Sérénade no 13 pour cordes en sol majeur ou Une petite musique de nuit KV 525 est une sérénade en sol majeur pour quintette à cordes composée par Mozart en 1787.",116,"fr:Une_petite_musique_de_nuit","c:9/94/Mozart-Lange.jpg"],["Q213728",198,"oeuvre","Variations Goldberg","C","Les Variations Goldberg ou « Aria avec quelques variations pour clavecin à deux claviers », sont une œuvre composée par Jean-Sébastien Bach au plus tard en 1740. Elle porte le numéro 988 dans le catalogue BWV. Cette œuvre constitue la partie IV du Clavier-Übung, publiée à Nuremberg par Balthasar Schmidt. C'est l'accomplissement de la forme « thème avec variations » et l'une des pièces pour clavier parmi les plus connues.",119,"fr:Variations_Goldberg","c:f/f5/Goldberg-titlepage.png"],["Q171277",199,"opera","Aida","PC","Aida est un opéra en quatre actes de Giuseppe Verdi, sur un livret d'Antonio Ghislanzoni d'après une intrigue d'Auguste Mariette, créé le 24 décembre 1871 à l'opéra khédival du Caire.",119,"fr:Aida","c:f/f2/Statue_of_the_god_Ptah%2C_granodiorite_-_Museo_Egizio_Turin_C_86_p02.jpg"],["Q185968",200,"opera","Carmen","E","Carmen est un opéra-comique en quatre actes de Georges Bizet, sur un livret d'Henri Meilhac et Ludovic Halévy. L’œuvre est une adaptation de la nouvelle Carmen de Prosper Mérimée. Carmen est une œuvre qui se rapproche de l'exotisme alors à la mode, qui se déroule dans une Espagne imaginaire. À la différence de Mérimée, Bizet choisit de faire de Carmen le personnage principal de cette histoire, à contre-pied du contrat social habituellement admis.","Carmen est un opéra-comique en quatre actes de Georges Bizet, sur un livret d'Henri Meilhac et Ludovic Halévy.","fr:Carmen_(opéra)","c:d/d4/Prudent-Louis_Leray_-_Poster_for_the_premi%C3%A8re_of_Georges_Bizet%27s_Carmen.jpg"],["Q221806",201,"opera","Cavalleria rusticana","PC","Cavalleria rusticana est un opéra en un acte unique, composé par Pietro Mascagni, sur un livret de Giovanni Targioni-Tozzetti et Guido Menasci. Le livret est inspiré d'une nouvelle de Giovanni Verga. Cet opéra est l'œuvre la plus célèbre du compositeur.",107,"fr:Cavalleria_rusticana","c:1/1e/Cavelleria_Rusticana%2C_scene_from_the_1890_premiere%2C_Teatro_Costanzi%2C_Rome.jpg"],["Q207410",202,"opera","Così fan tutte","R","Così fan tutte, ossia La scuola degli amanti, K.588, est un opera buffa en deux actes de Wolfgang Amadeus Mozart sur un livret en italien de Lorenzo Da Ponte, créé le 26 janvier 1790 au Burgtheater de Vienne. Il marque la troisième et dernière collaboration entre Mozart et Da Ponte, après Les Noces de Figaro et Don Giovanni.",119,"fr:Così_fan_tutte","c:7/7b/Cosi_fan_tutte_-_first_performance.jpg"],["Q156435",203,"opera","Der Freischütz","C","Der Freischütz est un opéra allemand de type singspiel en trois actes de Carl Maria von Weber, qui connut un triomphe lors de sa première le 18 juin 1821 au Königliches Schauspielhaus de Berlin.",117,"fr:Der_Freischütz","c:0/0f/Der_Freisch%C3%BCtz_um_1822.jpg"],["Q1194515",204,"opera","Der Hölle Rache kocht in meinem Herzen","C","« Der Hölle Rache kocht in meinem Herzen » est un air de l'opéra La Flûte enchantée de Mozart chanté au second acte par la Reine de la nuit en présence de sa fille Pamina. Culminant au contre-fa, il est considéré comme l'un des airs les plus virtuoses de l'art lyrique et requiert un soprano dramatique vocalisant avec aisance.",119,"fr:Der_Hölle_Rache_kocht_in_meinem_Herzen","c:3/3e/Mozart_magic_flute.jpg"],["Q746646",205,"opera","Dido and Æneas","C","Dido and Æneas Z. 626 est un opéra baroque en trois actes écrit au printemps 1689 par le compositeur anglais Henry Purcell, sur un livret de Nahum Tate.","Dido and Æneas Z.","fr:Dido_and_Æneas","c:d/dc/Heinrich_Friedrich_F%C3%BCger_006.jpg"],["Q192039",206,"opera","Don Giovanni","R","Don Giovanni, K. 527, est un opéra en deux actes et en langue italienne du genre « dramma giocoso » de Wolfgang Amadeus Mozart, créé au Théâtre des États de Prague le 29 octobre 1787, sur un livret de Lorenzo Da Ponte inspiré du mythe de « don Juan ».","Don Giovanni, K.","fr:Don_Giovanni","c:e/ed/Max_Slevogt_Das_Champagnerlied_Don_Giovanni_Andrade.jpg"],["Q50956",207,"opera","Eugène Onéguine","C","Eugène Onéguine, op. 24, est un opéra en trois actes et sept tableaux composé par Piotr Ilitch Tchaïkovski entre juin 1877 et janvier 1878, sur un livret russe de Constantin Chilovsky et du compositeur, inspiré d'Eugène Onéguine, roman en vers d'Alexandre Pouchkine. La première représentation eut lieu au Petit Théâtre du Collège impérial de musique, à Moscou, le 29 mars 1879.","Eugène Onéguine, op.","fr:Eugène_Onéguine_(opéra)","c:5/5d/Adamo_Didur_in_Eugene_Onegin.jpg"],["Q745951",208,"opera","Faust","C","Faust est un opéra en cinq actes de Charles Gounod, sur un livret de Jules Barbier et Michel Carré, fondé sur la légende éponyme et la pièce de Goethe, créé au Théâtre-Lyrique le 19 mars 1859.",112,"fr:Faust_(Gounod)","c:c/c9/Faust_grand_opera.jpg"],["Q193778",209,"opera","Fidelio","C","Fidelio, op. 72, est l’unique opéra de Ludwig van Beethoven, d'abord composé en 1804. La version définitive date de 1814. Le livret est de Joseph Sonnleithner.","Fidelio, op.","fr:Fidelio","c:0/08/Fotothek_df_pk_0000016_b_041_Szenenbilder.jpg"],["Q729659",210,"opera","Guillaume Tell","C","Guillaume Tell est un opéra en quatre actes de Gioachino Rossini, sur un livret d'Étienne de Jouy et Hippolyte Bis, aidés d'Armand Marrast et d'Adolphe Crémieux, d'après la pièce de Friedrich von Schiller, elle-même inspirée de la légende suisse. L'œuvre fut jouée pour la première fois le 3 août 1829 dans la salle Le Peletier à l'Opéra de Paris, en langue française. Traduit en italien sous le titre de Guglielmo Tell, la première est donnée à Lucques en 1831, les quatre actes furent réduits à trois.",115,"fr:Guillaume_Tell_(opéra)","c:1/1f/Eug%C3%A8ne_Du_Faget_-_Costume_designs_for_Guillaume_Tell_-_1-3._Laure_Cinti-Damoreau_as_Mathilde%2C_Adolphe_Nourrit_as_Arnold_Melchtal%2C_and_Nicolas_Levasseur_as_Walter_Furst.jpg"],["Q203470",211,"opera","Il trovatore","C","Le Trouvère ou Il trovatore est un opéra en quatre actes de Giuseppe Verdi, sur un livret de Salvatore Cammarano et Leone Emanuele Bardare, d'après le drame espagnol El Trovador d'Antonio García Gutiérrez. Il fut créé au Teatro Apollo de Rome le 19 janvier 1853, puis représenté à Paris, au Théâtre-Italien, dans sa version originale, le 23 décembre 1854.",115,"fr:Il_trovatore","c:c/ce/Trovatore_6886_Michelides.jpg"],["Q692648",212,"opera","L'amour est un oiseau rebelle","C","L'amour est un oiseau rebelle est une célèbre chanson d'amour-aria romantique et tragique, sur le rythme d'une habanera, du premier acte de l'opéra-comique Carmen de Georges Bizet de 1875, d'après la nouvelle Carmen de Prosper Mérimée de 1847.",110,"fr:L'amour_est_un_oiseau_rebelle","c:5/55/Act_I_%2830948589376%29.jpg"],["Q190237",213,"opera","L'Anneau du Nibelung","R","Der Ring des Nibelungen, ou L’Anneau du Nibelung en français, est un cycle de quatre opéras de Richard Wagner, inspiré de la mythologie germanique et nordique, et particulièrement de la Chanson des Nibelungen, un poème épique germanique du Moyen Âge, et de la littérature scandinave des sagas et des Eddas.",118,"fr:L'Anneau_du_Nibelung","c:a/a9/B%C3%BChnenbildentwurf_Walk%C3%BCre.JPG"],["Q724008",214,"opera","L'Orfeo","C","L’Orfeo, favola in musica est un opéra de Claudio Monteverdi sur un livret du poète Alessandro Striggio, fils du compositeur de même nom, Alessandro Striggio.",112,"fr:L'Orfeo","c:f/f2/Frontispiece_of_L%27Orfeo.jpg"],["Q188621",215,"opera","La Bohème","E","La Bohème est un opéra italien en quatre actes de Giacomo Puccini, sur un livret en italien de Giacosa et Illica, d’après le roman d’Henri Murger, Scènes de la vie de bohème, et son adaptation théâtrale La Vie de bohème. Composé entre 1892 et 1895, il fut créé le 1er février 1896 au Teatro Regio de Turin, sous la direction d'Arturo Toscanini.",113,"fr:La_Bohème","c:7/70/La_Boheme_poster_by_Hohenstein.PNG"],["Q1469717",216,"opera","La donna è mobile","C","La donna è mobile est l'aria que le personnage du Duc de Mantoue entonne dans le troisième et dernier acte de l'opéra Rigoletto de Giuseppe Verdi, créé en 1851. Son texte développe quelques vers de Victor Hugo dans Le roi s'amuse qui lui-même les aurait empruntés au roi François Ier.",117,"fr:La_donna_è_mobile",""],["Q5064",217,"opera","La Flûte enchantée","R","La Flûte enchantée, K. 620, dont le titre original en allemand est Die Zauberflöte, est un opéra singspiel composé par Mozart sur un livret d'Emanuel Schikaneder.","La Flûte enchantée, K.","fr:La_Flûte_enchantée","c:8/83/Papageno.jpg"],["Q186162",218,"opera","La traviata","R","La traviata est un opéra en trois actes de Giuseppe Verdi créé le 6 mars 1853 à La Fenice de Venise sur un livret de Francesco Maria Piave d'après le roman La Dame aux camélias d'Alexandre Dumas et son adaptation théâtrale.",116,"fr:La_traviata","c:4/44/La_Traviata_3773_Michelides.jpg"],["Q776107",219,"opera","Lakmé","C","Lakmé est un opéra en trois actes de Léo Delibes sur un livret en français d'Edmond Gondinet et Philippe Gille d'après le roman de Pierre Loti, Rarahu ou le Mariage de Loti, et inspiré des récits de voyage de Théodore Pavie, créé le 14 avril 1883 à l'Opéra-Comique de Paris.",118,"fr:Lakmé","c:3/37/Poster_for_the_premi%C3%A8re_of_L%C3%A9o_Delibes%27_Lakm%C3%A9_-_Original.jpg"],["Q208659",220,"opera","Le Barbier de Séville","R","Le Barbier de Séville est l'opéra le plus connu de Gioachino Rossini, sur un livret de Cesare Sterbini, créé en 1816 et considéré par beaucoup comme le chef-d'œuvre de l'opéra bouffe italien.",119,"fr:Le_Barbier_de_Séville_(Rossini)","c:c/cf/Figaro.jpg"],["Q335012",221,"opera","Les Contes d'Hoffmann","C","Les Contes d'Hoffmann est un opéra fantastique en cinq actes ou un prologue, trois actes et un épilogue selon la version de Jacques Offenbach, inspiré du conteur E. T. A. Hoffmann. Le livret est une adaptation que Jules Barbier a tirée de la pièce qu'il a écrite en 1851 avec Michel Carré.",112,"fr:Les_Contes_d'Hoffmann","c:f/f4/Les_Contes_d%27Hoffmann.jpg"],["Q201873",222,"opera","Les Noces de Figaro","R","Les Noces de Figaro est un opera buffa en 4 actes de Wolfgang Amadeus Mozart, sur un livret en italien de Lorenzo Da Ponte inspiré de la comédie de Beaumarchais, Le Mariage de Figaro.",116,"fr:Les_Noces_de_Figaro","c:f/f1/TheMarriageofFigaroOriginalPoster.jpg"],["Q56159",223,"opera","Les Pêcheurs de perles","C","Les Pêcheurs de perles est un opéra en trois actes de Georges Bizet sur un livret d'Eugène Cormon et Michel Carré, créé le 30 septembre 1863 au Théâtre-Lyrique. Il a été repris dans une nouvelle version après la mort du compositeur en 1893 à l’Opéra-Comique.",119,"fr:Les_Pêcheurs_de_perles","c:1/1b/Alessandro_allori%2C_pescatori_di_perle%2C_studiolo.jpg"],["Q23085",224,"opera","Lohengrin","C","Lohengrin est un opéra de Richard Wagner.",null,"fr:Lohengrin_(opéra)","c:2/23/Lohengrin_9264b-Michelides.jpg"],["Q244209",225,"opera","Lucia di Lammermoor","C","Lucia di Lammermoor est un opera seria en deux parties et trois actes de Gaetano Donizetti, sur un livret en italien de Salvadore Cammarano, d'après le roman La Fiancée de Lammermoor de Walter Scott. Il a été créé le 26 septembre 1835 au teatro San Carlo de Naples.",119,"fr:Lucia_di_Lammermoor","c:d/d1/Gaetano_Donizetti_-_Lucia_di_Lammermoor_-_stage_design_-_Francesco_Bagnara.jpg"],["Q19005",226,"opera","Madame Butterfly","R","Madame Butterfly est un opéra italien de Giacomo Puccini, sur un livret de Luigi Illica et de Giuseppe Giacosa, représenté pour la première fois le 17 février 1904 à la Scala de Milan. L'opéra est qualifié de « tragedia giapponese in due atti » dans la partition autographe, mais entre 1906 et 2016, il a été représenté le plus souvent dans une version révisée en trois actes, en scindant l'acte II en deux parties plus courtes. L'œuvre est dédiée à Hélène de Monténégro, reine d'Italie.",111,"fr:Madame_Butterfly","c:b/b4/Hohenstein_Madama_Butterfly.jpg"],["Q202230",227,"opera","Nabucco","C","Nabucco est un opéra en quatre actes de Giuseppe Verdi sur un livret de Temistocle Solera, tiré de Nabuchodonosor, drame d'Auguste Anicet-Bourgeois et de Francis Cornu et créé le 9 mars 1842 à la Scala de Milan. L'épisode biblique de l'esclavage des Hébreux à Babylone auquel s'identifiait la population milanaise alors sous occupation autrichienne est incarné par le chœur de la troisième partie et son célèbre Va, pensiero.",114,"fr:Nabucco","c:a/ae/Hanging_Gardens_of_Babylon.jpg"],["Q815342",228,"opera","Nessun dorma","R","Nessun dorma est un air pour ténor tiré de l'opéra Turandot de Giacomo Puccini créé en 1926.",null,"fr:Nessun_dorma","c:9/9b/GiacomoPuccini.jpg"],["Q320353",229,"opera","Norma","C","Norma est un opéra en deux actes de Vincenzo Bellini, sur un livret de Felice Romani, d'après la tragédie d'Alexandre Soumet Norma ou l'Infanticide. L'opéra fut créé le 26 décembre 1831 à la Scala de Milan sous la direction du compositeur avec Giuditta Pasta dans le rôle de Norma et Giulia Grisi dans celui de Adalgisa. Le rôle-titre était trop élevé pour Pasta et la première fut un échec. Après transposition d'un demi-ton, la quatrième représentation fut un triomphe.",117,"fr:Norma_(opéra)","c:0/09/Bellin-Norma_poster_for_1831_premiere.jpg"],["Q1137065",230,"opera","Orphée aux Enfers","C","Orphée aux Enfers est un opéra bouffe en deux actes et quatre tableaux d’Hector Crémieux et Ludovic Halévy, sur une musique de Jacques Offenbach, créé le 21 octobre 1858 au théâtre des Bouffes-Parisiens, puis dans une seconde version d'opéra féerique triomphale en quatre actes et douze tableaux le 7 février 1874 au théâtre de la Gaîté de Paris. Son Galop infernal d'Orphée aux Enfers est repris et arrangé en French cancan de 1868.",115,"fr:Orphée_aux_Enfers","c:a/a1/Orphee_adv.jpg"],["Q172324",231,"opera","Otello","C","Otello est un opéra en quatre actes de Giuseppe Verdi, sur un livret d'Arrigo Boito d'après Othello ou le Maure de Venise de William Shakespeare et créé au Teatro alla Scala de Milan, le 5 février 1887.",114,"fr:Otello_(Verdi)","c:8/89/Mario_Lanza_Otello.jpg"],["Q248644",232,"opera","Pagliacci","L","Pagliacci est un opéra italien en deux actes de Ruggero Leoncavallo, créé le 21 mai 1892 au Teatro Dal Verme à Milan.",null,"fr:Pagliacci","c:a/a9/Pagliacci_Original_Score_Cover.jpg"],["Q220340",233,"opera","Parsifal","PC","Parsifal est un « festival scénique sacré » en trois actes de Richard Wagner créé le 26 juillet 1882 lors du second festival de Bayreuth. Il se fonde sur Perceval ou le Conte du Graal de Chrétien de Troyes ainsi que l’épopée médiévale Parzival de Wolfram von Eschenbach.",115,"fr:Parsifal","c:9/90/Van_Dyck_Materna.jpg"],["Q740920",234,"opera","Porgy and Bess","PC","Porgy and Bess est un opéra composé par George Gershwin sur un livret d'Ira Gershwin et de DuBose Heyward, adaptation de la pièce de théâtre Porgy de Dorothy et DuBose Heyward, elle-même adaptée du court roman Porgy de DuBose Heyward. Ces trois œuvres traitent de la vie des Afro-Américains dans le quartier fictif de Catfish Row à Charleston, en Caroline du Sud, au début des années 1930.",117,"fr:Porgy_and_Bess","c:4/4f/Porgy_%26_Bess_6.jpg"],["Q189234",235,"opera","Rigoletto","PC","Rigoletto est un opéra italien en trois actes et quatre tableaux de Giuseppe Verdi, sur un livret de Francesco Maria Piave, d'après la pièce de Victor Hugo Le roi s'amuse, créé le 11 mars 1851 au théâtre de la Fenice à Venise. Il s'agit du dix-septième opéra du compositeur, formant avec Le Trouvère et La traviata, la « trilogie populaire » de Verdi.",116,"fr:Rigoletto","c:c/c2/Titta_Ruffo_as_Rigoletto.jpg"],["Q723407",236,"opera","Salome","C","Salome, en français Salomé, est un opéra en un acte de Richard Strauss sur un livret du même compositeur, d'après la traduction allemande de Hedwig Lachmann de la pièce de théâtre Salomé d'Oscar Wilde et créé le 9 décembre 1905 au Königliches Opernhaus de Dresde.",116,"fr:Salome_(opéra)","c:c/cc/Titian-salome.jpg"],["Q560619",237,"opera","Tannhäuser","C","Tannhäuser est un opéra de Richard Wagner, auteur du livret et de la musique.",null,"fr:Tannhäuser_(opéra)","c:9/98/Tischbein_-_Tannh%C3%A4user_1845.jpg"],["Q192941",238,"opera","Tosca","R","Tosca est un opéra en trois actes de Giacomo Puccini, sur un livret de Luigi Illica et Giuseppe Giacosa, d'après la pièce de Victorien Sardou. Il fut créé le 14 janvier 1900 au Teatro Costanzi de Rome.",115,"fr:Tosca","c:6/66/Puccini_Tosca.jpg"],["Q1324254",239,"opera","Tristan und Isolde","C","Tristan und Isolde est un opéra de Richard Wagner créé le 10 juin 1865 au théâtre royal de la Cour de Bavière à Munich sous la direction de Hans von Bülow.",118,"fr:Tristan_und_Isolde","c:5/5e/Tristan_and_Isolde_libretto_title.png"],["Q207990",240,"opera","Turandot","R","Turandot est un opéra en trois actes et cinq tableaux de Giacomo Puccini, sur un livret de Giuseppe Adami et Renato Simoni d'après Carlo Gozzi, créé le 25 avril 1926 à la Scala de Milan sous la direction de Toscanini. Il est inspiré de la comédie de Carlo Gozzi intitulée Turandot, déjà mise en musique en 1917 par Ferrucio Busoni sous le même nom de Turandot.",115,"fr:Turandot","c:4/41/Poster_Turandot.jpg"],["Q80284",241,"instrument","Alto","R","L'alto est un instrument à cordes frottées, plus grave, plus grand et plus épais que le violon, plus aigu, plus petit et plus fin que le violoncelle. Muni de quatre cordes, sa gamme de fréquences fondamentales va de 128 à 2 600 Hz.",117,"fr:Alto_(instrument_à_cordes)","c:c/cd/Bratsche.jpg",{"cats":["classique","instruments"]}],["Q178122",242,"instrument","Aria","C","Une aria est une pièce de musique écrite pour une voix seule dans un opéra ou dans toute autre forme musicale italienne de l'époque baroque ou ultérieure, accompagnée par une basse continue ou un ensemble d'instruments jusqu'au grand orchestre.",119,"fr:Aria","c:3/32/Aria.png"],["Q41425",243,"instrument","Ballet","PC","Le ballet est un genre dramatique dont l'action est figurée par des pantomimes et des danses. Ses origines remontent à la Renaissance italienne. Primitivement développé dans les cours d'Italie, le ballet a reçu ses lettres de noblesse en France, puis en Russie, en tant que danse-spectacle.","Le ballet est un genre dramatique dont l'action est figurée par des pantomimes et des danses.","fr:Ballet","c:0/0a/Edgar_Germain_Hilaire_Degas_033.jpg"],["Q31687",244,"instrument","Baryton","PC","Dans la musique occidentale, un baryton est un chanteur dont la voix possède une tessiture moyenne, entre les ténors et les basses. Dérivé du grec barytonos, le terme est souvent employé pour désigner une voix soliste, mais peut également être employé au sein d'un pupitre de chœur.",119,"fr:Baryton_(voix)","https://upload.wikimedia.org/wikipedia/commons/thumb/1/1b/Stimmlage_Bariton.svg/330px-Stimmlage_Bariton.svg.png"],["Q159998",245,"instrument","Basson","R","Le basson est un instrument de musique à vent de la famille des bois, qui apparaît à la fin du XVIe siècle en Italie sous le nom de fagotto.",116,"fr:Basson","c:6/6f/FoxBassoon.png",{"cats":["classique","instruments"]}],["Q200959",246,"instrument","Carnegie Hall","PC","Carnegie Hall ou le Carnegie Hall est une salle de concert new-yorkaise située à l'angle de la 7e avenue et de la 57e rue Ouest, juste au sud de Central Park, dans l'arrondissement de Manhattan. Le Stern Auditorium, sa principale salle, dispose de 2 804 places.",117,"fr:Carnegie_Hall","c:2/26/Carnegie_Hall_-_Full_%2848155558466%29.jpg"],["Q210970",247,"instrument","Castrat","E","Un castrat est un chanteur de sexe masculin ayant subi la castration avant sa puberté, dans le but de conserver le registre aigu de sa voix enfantine, tout en bénéficiant du volume sonore produit par la capacité thoracique d'un adulte. Le phénomène musical des castrats apparaît dans la deuxième moitié du XVIe siècle en Occident. Il se développe principalement en Italie et disparaît entre la fin du XIXe et le début du XXe siècle.",114,"fr:Castrat","c:a/a8/Bartolomeo_Nazari_-_Portrait_of_Farinelli_1734_-_Royal_College_of_Music_London.jpg"],["Q131186",248,"instrument","Chorale","C","Une chorale est un ensemble vocal amateur dont les membres, appelés choristes, chantent collectivement les différentes parties musicales destinées à ce type de formation sous la direction d'un chef de chœur.",118,"fr:Chorale","c:6/69/Diakonie-kantorei.jpg"],["Q8343",249,"instrument","Clarinette","E","La clarinette est un instrument de musique à vent de la famille des bois caractérisé par son anche simple et sa perce quasi cylindrique. Elle aurait été créée vers 1690 par Johann Christoph Denner à Nuremberg sur la base d'un instrument à anche simple plus ancien: le chalumeau. La clarinette soprano est le modèle le plus commun.",117,"fr:Clarinette","c:f/fa/Leitner%2BKraus_410_320.png",{"cats":["classique","instruments"]}],["Q81982",250,"instrument","Clavecin","E","Le clavecin est un instrument de musique à cordes pincées muni d'un ou plusieurs claviers. Chacune des cordes est pincée par un dispositif nommé sautereau.","Le clavecin est un instrument de musique à cordes pincées muni d'un ou plusieurs claviers.","fr:Clavecin","c:d/d4/Deless-10.jpg",{"cats":["classique","instruments"]}],["Q181040",251,"instrument","Clef","PC","Dans la notation musicale, une clef, ou clé, est un signe graphique placé au début de la portée qui indique la hauteur des notes associée à chaque ligne.",118,"fr:Clef_(musique)","https://upload.wikimedia.org/wikipedia/commons/thumb/2/27/Music_notation_signature.svg/330px-Music_notation_signature.svg.png"],["Q9748",252,"instrument","Concerto","C","Le concerto est un genre musical composé généralement de trois mouvements, où un ou plusieurs solistes dialoguent avec un orchestre. D'origine italienne, il se développa pendant la période baroque et fut une des formes musicales les plus prisées pendant les périodes classique et romantique.",118,"fr:Concerto","c:4/46/210917_Competition_Final_Day_122_copy.jpg"],["Q80019",253,"instrument","Contrebasse","E","La contrebasse est un instrument grave de la famille des instruments à cordes. Avant l'octobasse, la contrebasse est le plus grand et l'un des plus graves instruments de cette famille. À la différence des autres instruments de la famille, qui s'accordent en quintes, elle s'accorde aujourd’hui en quartes, essentiellement pour des raisons de facilité de doigté.","La contrebasse est un instrument grave de la famille des instruments à cordes.","fr:Contrebasse","c:d/d3/AGK_bass1_full.jpg",{"cats":["classique","instruments"]}],["Q223166",254,"instrument","Contreténor","C","Dans la musique occidentale et, plus précisément, la musique classique, un contre-ténor est le type de voix masculine utilisant principalement sa voix de fausset, et dont la tessiture peut correspondre à celle d'un soprano, à celle d'un alto ou à celle d'un contralto.",117,"fr:Contreténor","c:2/2e/Cameron_Shahbazi_on_Music_Monday.jpg"],["Q163759",255,"instrument","Cor d'harmonie","R","Le cor d'harmonie est un instrument à vent de la famille des cuivres. C'est la version moderne du cor à pistons inventé au XIXe siècle sur la base du cor naturel.","Le cor d'harmonie est un instrument à vent de la famille des cuivres.","fr:Cor_d'harmonie","c:6/63/French_horn_front.png",{"cats":["classique","instruments"]}],["Q190172",256,"instrument","Cymbale","C","La cymbale est un instrument de musique de la famille des percussions idiophones, consistant en un disque de métal généralement percé en son centre. Il est confectionné selon différents procédés. Sa forme générale est précisée par un tournage en machine, qui lui donne une forme circulaire quasiment parfaite. Le plus souvent, elle forme un dôme en son centre.",114,"fr:Cymbale","c:a/ae/Cymbal_NAM_Athens_7959.jpg",{"cats":["classique","instruments"]}],["Q320341",257,"instrument","Célesta","PC","Le célesta est un instrument de musique de la famille des percussions muni d'un clavier, inventé en 1886. C'est un hybride entre le glockenspiel et le piano, les marteaux actionnés par les touches du clavier frappant des lames métalliques.","Le célesta est un instrument de musique de la famille des percussions muni d'un clavier, inventé en 1886.","fr:Célesta","c:6/6e/Celesta.jpg",{"cats":["classique","instruments"]}],["Q6989196",258,"instrument","Direction d'orchestre","C","La direction d'orchestre est l'art de diriger l'interprétation de la musique d'un orchestre ou d'une chorale en concert. Les principales tâches du chef d'orchestre sont de définir le tempo, d'assurer les entrées correctes des différents membres de l'ensemble et de « modeler » le phrasé, le cas échéant. Pour transmettre ses idées et son interprétation, un chef communique avec ses musiciens principalement par des gestes de la main, et généralement, mais pas toujours, à l'aide d'une baguette.","La direction d'orchestre est l'art de diriger l'interprétation de la musique d'un orchestre ou d'une chorale en concert.","fr:Direction_d'orchestre","c:2/2f/Bundesarchiv_Bild_183-R92264%2C_Herbert_von_Karajan.jpg"],["Q157596",259,"instrument","Festival de Bayreuth","C","Le Festival de Bayreuth est un festival d'opéra fondé en 1876 par Richard Wagner et consacré à l'exécution de ses dix principaux opéras. Il se tient chaque été au palais des festivals de Bayreuth, en Bavière, un théâtre conçu par Wagner pour pouvoir réaliser sa conception particulière de l'ouvrage lyrique comme « œuvre d'art totale ».",117,"fr:Festival_de_Bayreuth","c:6/61/Bayreuth_Festspielhaus_2006-07-16.jpg"],["Q11405",260,"instrument","Flûte","E","Flûte est un terme générique désignant un instrument de musique à vent dont le son est créé par l'oscillation d'un jet d’air autour d'un biseau droit, en encoche ou en anneau.",118,"fr:Flûte","c:8/84/D%C3%A9tail_de_Le_sommeil_de_l%27enfant_J%C3%A9sus_-_FRANCESCO_TREVISANI.jpg",{"cats":["classique","instruments"]}],["Q181014",261,"instrument","Fugue","C","Une fugue est une technique d'écriture musicale, née au XVIIe siècle, du nom de « fuga », une composition entièrement fondée sur ce procédé: « fuir », parce que l'auditeur a l'impression que le thème ou sujet de la fugue fuit d'une voix à l'autre. C’est une forme de composition parmi les plus exigeantes, exploitant les ressources du contrepoint et le principe de l'imitation.",117,"fr:Fugue","c:f/f1/Ricercare_a_6_from_The_Musical_Offering.jpg"],["Q47369",262,"instrument","Harpe","E","La harpe est un instrument de musique à cordes pincées de forme le plus souvent triangulaire, muni de cordes tendues de longueurs variables dont les plus courtes donnent les notes les plus aiguës. C'est un instrument asymétrique, contrairement à la lyre dont les cordes sont tendues entre deux montants parallèles. L'instrumentiste qui joue de la harpe est appelé harpiste.",119,"fr:Harpe","c:a/a9/Guillon_Lethi%C3%A8re_-_Portrait_of_Ad%C3%A8le_Papin_playing_harp.jpg",{"cats":["classique","instruments"]}],["Q8377",263,"instrument","Hautbois","E","Le hautbois est un instrument de musique à vent de la famille des bois, de perce conique et dont le son est créé par la vibration d'une anche double au passage du souffle. Son timbre peut être puissant et sonore ou doux et charmeur, clair ou plein de rondeur et de chaleur. Le musicien jouant de cet instrument est un hautboïste.",119,"fr:Hautbois","c:e/e2/M%C3%B6nnig%2C_Oboe_Modell_155_Albrecht_Mayer.jpg",{"cats":["classique","instruments"]}],["Q503246",264,"instrument","Juilliard School","E","La Juilliard School est un conservatoire supérieur privé de musique et des arts du spectacle de New York de réputation internationale. Ses locaux sont situés au Lincoln Center, dans l'arrondissement de Manhattan. Elle accueille chaque année 800 étudiants dans ses sections musique, danse et art dramatique.",118,"fr:Juilliard_School","c:d/da/Juilliard_School_-_Alice_Tully_Hall.jpg"],["Q5471",265,"instrument","La Scala","PC","La Scala de Milan, ou simplement la Scala, est un théâtre d'opéra situé à Milan, en Italie. Il a été inauguré le 3 août 1778.","La Scala de Milan, ou simplement la Scala, est un théâtre d'opéra situé à Milan, en Italie.","fr:La_Scala","c:3/3f/Milan_-_Scala_-_Facade.jpg",{"cats":["classique","italie"]}],["Q180733",266,"instrument","Luth","R","Le luth est un instrument à cordes pincées. Dans le système Hornbostel-Sachs, le terme désigne aussi de manière générale tout instrument ayant les cordes parallèles à un manche.","Le luth est un instrument à cordes pincées.","fr:Luth","c:2/28/8-course-tenor-renaissance-lute-04.jpg",{"cats":["classique","instruments"]}],["Q10583424",267,"instrument","Metropolitan Opera","C","Le Metropolitan Opera ou « Met » est une salle d'opéra inaugurée en 1966 dans le centre culturel du Lincoln Center, dans l'arrondissement de Manhattan à New York, aux États-Unis.",115,"fr:Metropolitan_Opera","c:e/ef/MET_Opera_%2848047450723%29.jpg"],["Q186506",268,"instrument","Mezzo-soprano","PC","La mezzo-soprano est une voix féminine située entre la soprano et l'alto. Carmen, dans l'opéra de Bizet, est l'un de ses rôles les plus célèbres.",116,"fr:Mezzo-soprano","https://upload.wikimedia.org/wikipedia/commons/thumb/5/53/Stimmlage_Mezzosopran.svg/330px-Stimmlage_Mezzosopran.svg.png"],["Q8361",269,"instrument","Musique baroque","PC","La musique baroque est une période qui apparaît avec le baroque au xviie siècle et évolue jusqu'à la fin du siècle suivant. Divisée en plusieurs périodes, la musique baroque recouvre différents genres musicaux, depuis la musique instrumentale jusqu'à l'opéra, et est à l'origine de ce dernier. La musique baroque s'étend géographiquement sur une bonne partie de l'Europe de l'ouest, dont les principaux pays représentants sont la France et l'Italie, et trouve un écho remarquable dans les pays germaniques.",114,"fr:Musique_baroque","c:5/50/Baschenis_-_Musical_Instruments.jpg"],["Q189201",270,"instrument","Musique de chambre","C","Une œuvre de musique de chambre est une composition musicale destinée à un petit ensemble de cordes, bois, cuivres ou percussions, qui traditionnellement et avant l'affirmation des concerts publics, pouvait tenir dans la « grande chambre » d'un palais. Chaque partie est écrite pour un seul instrumentiste sans qu'il y ait à l'origine ni chef d'orchestre ni soliste attitré.",117,"fr:Musique_de_chambre","c:6/61/TrioSonata.jpg"],["Q17723",271,"instrument","Musique de la période classique","PC","La musique de la période classique recouvre par convention la musique écrite entre la mort de Johann Sebastian Bach soit 1750 et le début de la période romantique, soit les années 1820. Par extension, on appelle « musique classique » toute la musique savante européenne, de la musique du Moyen Âge à la musique contemporaine. On dissocie la musique de style classique d'avec la musique classique opposée à la musique populaire, en Occident ou ailleurs.",115,"fr:Musique_de_la_période_classique","c:9/9e/Mozart_family_crop.jpg"],["Q837182",272,"instrument","Musique impressionniste","C","La « musique impressionniste » est un genre musical appartenant à la période moderne, qui voit le jour en Europe dans le dernier quart du XIXe siècle et dont le principal représentant est Claude Debussy.",117,"fr:Musique_impressionniste","c:1/19/G._Caillebotte_-_Jeune_homme_au_piano.jpg"],["Q207591",273,"instrument","Musique romantique","C","La musique romantique est un type de musique qui domine en Europe tout au long du XIXe siècle. Ce courant musical aux formes variées, qui met au premier plan l'expression de l'émotion, s'inscrit dans le mouvement esthétique européen du romantisme. Celui-ci touche les arts et la littérature sous l'influence de l'Angleterre et de l'Allemagne, où s'approfondit une nouvelle sensibilité à partir de la fin du XVIIIe siècle.","La musique romantique est un type de musique qui domine en Europe tout au long du XIXe siècle.","fr:Musique_romantique","c:8/8d/Berlioz_young.jpg"],["Q233861",274,"instrument","Notation musicale","C","La notation musicale est la transcription sur un support d'une œuvre musicale afin de la conserver, de la diffuser et de l'interpréter ultérieurement.",117,"fr:Notation_musicale","c:d/d3/Bachlut1.png"],["Q1344",275,"instrument","Opéra","PC","Un opéra est, dans la musique classique occidentale, une œuvre musicale et théâtrale pour un orchestre et des chanteurs. L'opéra est l’une des formes de l'art lyrique du théâtre musical occidental.","Un opéra est, dans la musique classique occidentale, une œuvre musicale et théâtrale pour un orchestre et des chanteurs.","fr:Opéra","c:e/ed/Alma_Deutscher_conducts_her_opera_Cinderella%2C_2022.jpg",{"cats":["classique","italie"]}],["Q209937",276,"instrument","Opéra d'État de Vienne","C","L'opéra d'État de Vienne est une compagnie publique d’opéra et de ballet située à Vienne. C'est l’un des plus prestigieux opéras du monde, et l’une des toutes premières institutions culturelles de la capitale autrichienne. C'est aussi le nom du bâtiment inauguré en 1869 qui abrite cette compagnie","L'opéra d'État de Vienne est une compagnie publique d’opéra et de ballet située à Vienne.","fr:Opéra_d'État_de_Vienne","c:c/c3/%C3%93pera%2C_Viena%2C_Austria%2C_2020-01-31%2C_DD_76.jpg"],["Q187840",277,"instrument","Opéra Garnier","R","L'opéra Garnier, ou palais Garnier, est un théâtre national qui a la vocation d'être une académie de musique, de chorégraphie et de poésie lyrique; il est un élément majeur du patrimoine du 9e arrondissement de Paris et de la capitale. Il est situé place de l'Opéra, à l'extrémité nord de l'avenue de l'Opéra et au carrefour de nombreuses voies.",112,"fr:Opéra_Garnier","c:6/6d/Paris_Palais_Garnier_2010-04-06_16.55.07.jpg",{"cats":["classique","france","architecture"]}],["Q85477",278,"instrument","Oratorio","C","Un oratorio est une œuvre lyrique dramatique représentée sans mise en scène, ni costumes, ni décors. Il peut toutefois y avoir une mise en espace. La partition est généralement composée pour voix solistes, chœur avec orchestre, avec parfois un narrateur. Son sujet est le plus souvent religieux. Il peut être aussi profane. Formellement assez proche de la cantate et de l’opéra, l'oratorio comprend généralement une ouverture, des récitatifs, des airs et des chœurs.","Un oratorio est une œuvre lyrique dramatique représentée sans mise en scène, ni costumes, ni décors.","fr:Oratorio","c:3/3d/1808PerformanceOfHaydnCreation.jpg"],["Q42998",279,"instrument","Orchestre","C","Un orchestre est un ensemble musical formé d'instrumentistes réunis pour l'exécution d'une œuvre musicale. Le nombre et la combinaison des interprètes dépendent du compositeur, de l'époque et du genre du répertoire abordé. Le plus souvent, il est dirigé par un chef d'orchestre.","Un orchestre est un ensemble musical formé d'instrumentistes réunis pour l'exécution d'une œuvre musicale.","fr:Orchestre","c:5/51/Orquesta_Filarmonica_de_Jalisco.jpg"],["Q152222",280,"instrument","Orchestre philharmonique de Berlin","C","L'Orchestre philharmonique de Berlin est un orchestre symphonique allemand créé en 1882. Il compte parmi les orchestres les plus réputés au monde, autant pour son statut en Allemagne que pour ses productions diffusées dans le monde entier, y compris discographiques. Jouissant d'un prestige reconnu, il accueille parmi les meilleurs musiciens du monde dans son sein, et collabore avec des solistes de premier plan.","L'Orchestre philharmonique de Berlin est un orchestre symphonique allemand créé en 1882.","fr:Orchestre_philharmonique_de_Berlin","c:5/5c/Berlin_Philharmonie_asv2018-05_img1.jpg"],["Q281460",281,"instrument","Orgue","R","L'orgue est un instrument à vent multiforme dont la caractéristique est de produire les sons à l’aide d’ensembles de tuyaux sonores accordés suivant une gamme définie et alimentés par une soufflerie, chaque tuyau émettant un son de hauteur et de timbre uniques. L'orgue est joué majoritairement à l’aide d’un ou plusieurs claviers incluant souvent un pédalier.",116,"fr:Orgue","c:4/4e/Laon_Cathedral_Organ_01.JPG",{"cats":["classique","instruments"]}],["Q5994",282,"instrument","Piano","M","Le piano est un instrument de musique polyphonique, à clavier, de la famille des cordes frappées. Le son est produit lorsque l'on appuie sur des touches noires ou blanches, grâce à l'action d'un marteau tapant la corde correspondant au placement de la touche et au son désiré. Il comporte 52 touches blanches et 36 touches noires, soit un total de 88 touches. Il y a deux sortes de pianos:","Le piano est un instrument de musique polyphonique, à clavier, de la famille des cordes frappées.","fr:Piano","c:3/3d/Two_pianos_-_grand_piano_and_upright_piano.jpg",{"cats":["classique","instruments"]}],["Q83509",283,"instrument","Piccolo","PC","Le piccolo est un instrument de musique à vent, plus précisément un bois appartenant à la famille de la flûte traversière. Il est également appelé « petite flûte ». Il se distingue du fifre, dont il dérive, par la présence d'un clétage.",109,"fr:Piccolo_(instrument)","c:1/1e/Range_piccolo.png",{"cats":["classique","instruments"]}],["Q51616",284,"instrument","Requiem","C","Le requiem, ou messe de requiem, est une messe de l'Église catholique célébrée lors de funérailles ou de cérémonies du souvenir. Cette prière pour les âmes des défunts est aussi connue sous le nom latin de Missa pro defunctis ou Missa defunctorum. Elle est parfois pratiquée par d’autres Églises chrétiennes comme les Églises anglicane et orthodoxe.",118,"fr:Requiem","c:0/00/Folio_199v_-_A_Funeral_Service.jpg"],["Q55018",285,"instrument","Royal Opera House","C","La Royal Opera House est un opéra et un rendez-vous d'art à Londres. Il est désigné également parfois sous le nom de Covent Garden, du nom du quartier de Covent Garden où il est situé. Le bâtiment sert de résidence au Royal Opera, au Royal Ballet et à l'orchestre du Royal Opera House. Il a récemment changé d'appellation pour se nommer Royal Ballet and Opera.","La Royal Opera House est un opéra et un rendez-vous d'art à Londres.","fr:Royal_Opera_House","c:b/bb/Royal_Opera_House_and_ballerina.jpg"],["Q131269",286,"instrument","Sonate","C","Une sonate est une composition instrumentale de musique classique à plusieurs mouvements. Il ne faut pas confondre le nom de sonate avec celui de l'une des formes musicales les plus importantes, la forme sonate. Certains mouvements d'une sonate sont, d'ailleurs, souvent écrits en respectant la forme sonate.","Une sonate est une composition instrumentale de musique classique à plusieurs mouvements.","fr:Sonate","c:2/2a/Beethoven_opus_101_manuscript.jpg"],["Q30903",287,"instrument","Soprano","PC","Dans la musique occidentale, au sein de la musique classique, le terme soprano désigne avant tout le pupitre dont la tessiture se situe « au-dessus ».",116,"fr:Soprano","https://upload.wikimedia.org/wikipedia/commons/thumb/a/a6/Stimmlage_Sopran.svg/330px-Stimmlage_Sopran.svg.png"],["Q9734",288,"instrument","Symphonie","C","Une symphonie est une œuvre musicale instrumentale savante, de proportions généralement vastes, comprenant plusieurs mouvements joints ou disjoints et faisant appel aux ressources de l'orchestre symphonique.",116,"fr:Symphonie","c:6/6e/8_de_Malher81_%2853126024057%29.jpg"],["Q189737",289,"instrument","Timbales","PC","Les timbales sont des instruments à percussion constitués d'un fût en cuivre couvert d'une peau.",null,"fr:Timbales_(musique_classique)","c:a/a6/Standard_timpani_setup.jpg",{"cats":["classique","instruments"]}],["Q8350",290,"instrument","Trombone","R","Le trombone est un instrument de musique à vent et à embouchure de la famille des cuivres clairs. Le terme désigne implicitement le trombone à coulisse caractérisé par l'utilisation d'une coulisse télescopique, mais il existe également le trombone à pistons. Le trombone à coulisse est l'un des rares instruments à vent dont la maîtrise ne nécessite pas l'utilisation individuelle des doigts.","Le trombone est un instrument de musique à vent et à embouchure de la famille des cuivres clairs.","fr:Trombone_(instrument)","c:a/a3/Trombone_CG_Bach42AG.jpg",{"cats":["classique","instruments"]}],["Q8338",291,"instrument","Trompette","E","La trompette est un instrument de musique à vent de la famille des cuivres clairs. Elle est fabriquée dans un tube de 1,50 m de long comme le cornet. Le métal utilisé pour fabriquer la trompette est surtout le laiton. Pour en jouer, on utilise souvent 3 pistons ainsi que de l'air.","La trompette est un instrument de musique à vent de la famille des cuivres clairs.","fr:Trompette","https://upload.wikimedia.org/wikipedia/commons/thumb/9/9f/Range_trumpet.svg/330px-Range_trumpet.svg.png",{"cats":["classique","instruments"]}],["Q131168",292,"instrument","Tuba","R","Le tuba est un instrument de musique appartenant à la famille des cuivres. Par la variété de ses tailles et de ses formes, il constitue une sous-famille des cuivres. Le mot « tuba » provient du latin et désignait à l'époque romaine une grande trompette incurvée utilisée dans le contexte militaire.","Le tuba est un instrument de musique appartenant à la famille des cuivres.","fr:Tuba_(instrument)","c:4/49/Two_F_tubas.jpg",{"cats":["classique","instruments"]}],["Q27914",293,"instrument","Ténor","PC","Dans la musique occidentale, le mot ténor désigne la tessiture d'une voix ou le registre d'un instrument situés entre l'alto et la basse. Dans la musique vocale, elle correspond à la voix masculine la plus aiguë.",117,"fr:Ténor","https://upload.wikimedia.org/wikipedia/commons/thumb/d/d9/Stimmlage_Tenor.svg/330px-Stimmlage_Tenor.svg.png"],["Q8355",294,"instrument","Violon","M","Le violon est un instrument à cordes frottées, constitué de plus de 70 pièces de bois collées ou assemblées les unes aux autres. Le violon possède quatre cordes accordées généralement à la quinte, que l'instrumentiste, appelé violoniste, frotte avec un archet ou pince avec l'index ou le pouce.",116,"fr:Violon","c:1/1b/Violin_VL100.png",{"cats":["classique","instruments"]}],["Q8371",295,"instrument","Violoncelle","E","Le violoncelle est un instrument à cordes frottées, pincées ou plus rarement frappées avec le bois de l'archet, de la famille des cordes frottées, qui compte aussi notamment le violon, l'alto et la contrebasse. Il se joue assis et tenu entre les jambes; il repose maintenant sur une pique escamotable, mais fut longtemps joué posé entre les jambes, sur les mollets ou sur la poitrine.",117,"fr:Violoncelle","c:5/5f/Cello_front_side.png",{"cats":["classique","instruments"]}]]]);